  /* ==================== 1. SKB KEBIJAKAN (+50 Soal -> Total 105 Soal) ==================== */
  const KEBIJAKAN_EXP = [
    ['SAKIP, Reformasi Birokrasi & Zona Integritas', 'kbj-exp-pohon-kinerja-01', 'Perhatikan bagan Pohon Kinerja (Cascading SAKIP) di bawah. Jika sebuah dinas menemukan banyak belanja perjalanan dinas penunjang yang tidak memiliki hubungan logis menuju Intermediate Outcome, keputusan penganggaran berbasis kinerja yang tepat adalah...', [
      'A. Tetap mempertahankan pagu belanja penunjang karena sudah menjadi kebiasaan rutin tahunan',
      'B. Melakukan refocussing / rasionalisasi belanja penunjang non-IKU dan menggesernya ke subkegiatan penyumbang langsung CSF dan Outcome',
      'C. Mengubah nama subkegiatan saja pada aplikasi SIPD tanpa mengubah output kerjanya',
      'D. Menambah pegawai honorer untuk menyerap sisa pagu anggaran sebelum Desember',
      'E. Membagi rata anggaran penunjang ke seluruh bidang agar serapan kas tinggi'
    ], 1, 'Money Follow Program + Cascading Pohon Kinerja: pangkas aktivitas yang tak menyokong Critical Success Factor!', 'Sesuai PermenPANRB tentang SAKIP, setiap rupiah belanja wajib tertaut secara logis (cause-effect) dalam Pohon Kinerja menuju Ultimate Outcome.', SVG_POHON_KINERJA],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-rpjpn-2045-02', 'Dokumen perencanaan pembangunan jangka panjang nasional 20 tahunan periode 2025–2045 yang ditetapkan dengan Undang-Undang (UU No. 59/2024) mengusung visi Indonesia Emas dan diterjemahkan ke jangka menengah nasional setiap 5 tahun dalam bentuk...', ['A. RKP tahunan saja', 'B. RPJMN melalui Peraturan Presiden', 'C. Renja KL melalui Keputusan Sekjen', 'D. RKPD Provinsi oleh DPRD', 'E. DPA SKPD oleh Bendahara'], 1, 'RPJPN (UU, 20 th) -> dijabarkan ke RPJMN (Perpres, 5 th) -> RKP (Perpres, 1 th)!', 'UU 25/2004 SPPN menetapkan hierarki pusat: RPJPN (20 th, UU), RPJMN (5 th, Perpres), dan RKP (1 th, Perpres).'],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-rpjmd-teknokratik-03', 'Rancangan teknokratik RPJMD wajib disiapkan Bappeda sebelum kepala daerah terpilih dilantik dengan basis...', ['A. Usulan tim sukses pasangan calon tanpa indikator statistik', 'B. Kajian ilmiah objektif, data makro daerah, KLHS, serta evaluasi pencapaian periode sebelumnya', 'C. Hasil lelang proyek konstruksi tahun berikutnya', 'D. Instruksi lisan ketua komisi anggaran DPRD', 'E. Perkiraan penerimaan pajak daerah satu triwulan saja'], 1, 'Teknokratik = netral, berbasis bukti ilmiah, KLHS, dan data pembangunan objektif!', 'Rancangan Teknokratik RPJMD disusun sebelum Pilkada usai sebagai kerangka ilmiah pembangunan 5 tahunan berbasis data valid dan Kajian Lingkungan Hidup Strategis (KLHS).'],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-musrenbang-delay-04', 'Dalam tahapan penyusunan RKPD tahunan, pelaksanaan Musrenbang Kecamatan dan Forum Perangkat Daerah bertujuan untuk menyinkronkan...', ['A. Usulan belanja pegawai pusat dengan tarif pajak penghasilan', 'B. Pendekatan perencanaan bottom-up masyarakat dengan rencana teknokratik top-down Perangkat Daerah', 'C. Putusan pengadilan tata usaha dengan peraturan menteri', 'D. Laporan kas bendahara pengeluaran dengan rekening koran bank', 'E. Pengangkatan pejabat pimpinan tinggi pratama dengan BKN'], 1, 'Musrenbang menjembatani aspirasi warga (bottom-up) dengan prioritas strategis OPD (top-down)!', 'Permendagri 86/2017 memadukan empat pendekatan perencanaan (teknokratik, partisipatif/Musrenbang, politis, serta top-down dan bottom-up).'],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-pagu-indikatif-05', 'Urutan dokumen penganggaran tahunan pemerintah pusat/daerah sebelum Rancangan APBD diserahkan ke DPRD yang benar adalah...', ['A. APBD -> KUA-PPAS -> RKPD -> RKA-SKPD', 'B. RKPD -> KUA-PPAS -> Surat Edaran RKA-SKPD -> Rancangan APBD', 'C. RKA-SKPD -> DPA -> RKPD -> KUA-PPAS', 'D. DPA -> LKPJ -> KUA -> RKPD', 'E. RKP -> LKJIP -> DPA -> Perda'], 1, 'Alur siklus: Perencanaan (RKPD) -> Kebijakan Umum Anggaran (KUA-PPAS) -> RKA-SKPD -> RAPBD!', 'RKPD menjadi acuan penyusunan KUA-PPAS antara Kepala Daerah dan DPRD, lalu tiap OPD menyusun RKA-SKPD menjadi RAPBD.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-agenda-setting-06', 'Menurut William Dunn dan model siklus kebijakan publik, tahap ketika berbagai isu sosial disaring dan diperjuangkan oleh aktor kebijakan agar masuk ke perhatian resmi pemerintah disebut...', ['A. Policy Evaluation', 'B. Agenda Setting (Penyusunan Agenda)', 'C. Policy Termination', 'D. Policy Legitimation', 'E. Budget Execution'], 1, 'Isu naik ke meja pengambil keputusan = Agenda Setting!', 'Agenda Setting adalah fase kritis menyaring masalah publik agar mendapat prioritas masuk ke agenda perumusan kebijakan resmi.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-ria-regulatory-07', 'Instrumen Regulatory Impact Analysis (RIA) wajib digunakan perancang/analis kebijakan sebelum menerbitkan regulasi baru guna memastikan bahwa...', ['A. Aturan baru pasti menaikkan jumlah perizinan usaha agar pendapatan retribusi naik', 'B. Manfaat sosial-ekonomi regulasi jauh melebihi beban biaya kepatuhan yang ditimbulkan bagi publik & dunia usaha', 'C. Regulasi dibuat sesingkat mungkin tanpa uji konsultasi pemangku kepentingan', 'D. Semua pelanggaran otomatis dikenai pidana kurungan maksimal', 'E. Aturan serupa milik daerah tetangga disalin persis tanpa penyesuaian'], 1, 'RIA = analisis Cost-Benefit regulasi + alternatif non-regulasi agar tidak over-regulated!', 'RIA menilai masalah akar, tujuan, opsi (termasuk opsi tanpa aturan baru), analisis biaya-manfaat (CBA), serta konsultasi publik.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-error-type-3-08', 'Kesalahan paling fatal dalam analisis kebijakan publik yang disebut William Dunn sebagai "Type III Error" (Kesalahan Tipe III) adalah...', ['A. Salah menghitung persentase serapan anggaran di akhir kuartal', 'B. Memberikan solusi yang benar tetapi untuk perumusan masalah yang salah (solving the wrong problem)', 'C. Terlambat mencetak dokumen Policy Brief saat rapat pimpinan', 'D. Kurang menebalkan garis tabel pada laporan kinerja', 'E. Salah mengetik nomor surat pengantar peraturan'], 1, 'Type III Error Dunn = Merumuskan masalah yang KELIRU sehingga solusinya meleset total!', 'Problem Structuring krusial karena kesalahan merumuskan masalah (Type III Error) membuat kebijakan mahal sekalipun gagal menyelesaikan masalah riil.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-delphi-focus-09', 'Untuk meramalkan dampak jangka panjang penerapan pajak karbon terhadap UMKM tanpa menimbulkan bias dominasi satu tokoh vokal dalam rapat tatap muka, metode peramalan kebijakan paling tepat dipakai adalah...', ['A. Voting terbuka di media sosial', 'B. Metode Delphi (survei pakar anonim berulang lintas putaran hingga konsensus)', 'C. Wawancara tunggal dengan seorang vendor IT', 'D. Extrapolasi linear 1 bulan terakhir saja', 'E. Undian acak sederhana tanpa melibatkan ahli'], 1, 'Delphi = panel pakar ANONIM bertahap mencegah efek bandwagon & dominasi tokoh!', 'Metode Delphi mengumpulkan penilaian pakar independen secara anonim dalam beberapa putaran disertai umpan balik statistik.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-policy-brief-10', 'Ciri utama Policy Brief yang efektif disampaikan Analis Kebijakan kepada Menteri atau Kepala Daerah dibanding artikel jurnal akademik adalah...', ['A. Memuat minimal 40 halaman tinjauan pustaka teoretis', 'B. Padat (2–4 halaman), fokus pada solusi actionable, perbandingan opsi kebijakan, dan rekomendasi konkret siap diputuskan', 'C. Menyembunyikan kelemahan opsi rekomendasi agar pimpinan langsung setuju', 'D. Menggunakan jargon statistik kompleks tanpa ringkasan eksekutif', 'E. Tidak mencantumkan implikasi biaya anggaran sama sekali'], 1, 'Policy Brief = ringkas, berbasis bukti, membandingkan opsi (termasuk risiko/biaya), dan rekomendasi tegas!', 'Eksekutif memiliki keterbatasan waktu sehingga Policy Brief harus ringkas, visual mudah dipindai, netral membandingkan opsi, dan actionable.'],
    ['SAKIP, Reformasi Birokrasi & Zona Integritas', 'kbj-exp-sakip-ikui-11', 'Indikator Kinerja Utama (IKU) Pemerintah Daerah berupa "Jumlah Rapat Koordinasi Pengendalian Inflasi yang Diselenggarakan" dikritik evaluator KemenPANRB karena indikator tersebut baru mencerminkan level...', ['A. Ultimate Outcome', 'B. Activity / Input-Process belaka, bukan Result/Outcome kendali harga', 'C. Impact Makroekonomi Nasional', 'D. Net Present Value Daerah', 'E. Indeks Persepsi Korupsi Global'], 1, '"Jumlah rapat / jumlah dokumen / jumlah bimtek" = output aktivitas, bukan dampak (Outcome)!', 'SAKIP menuntut IKU berorientasi hasil nyata (misal Indeks Perkembangan Harga/Inflasi terkendali), bukan sekadar menghitung rapat.'],
    ['SAKIP, Reformasi Birokrasi & Zona Integritas', 'kbj-exp-rb-tematik-12', 'Kebijakan Reformasi Birokrasi Berdampak (PermenPANRB 3/2023) menambahkan fokus "RB Tematik" di luar RB General yang diarahkan langsung menyasar 4 prioritas nasional yaitu...', ['A. Pembangunan gedung kantor mewah di ibu kota provinsi', 'B. Pengentasan kemiskinan, peningkatan investasi, digitalisasi administrasi pemerintahan berdampak, serta prioritas Presiden (stunting/inflasi/PDN)', 'C. Penambahan jumlah rapat seremonial lintas instansi', 'D. Penghapusan seluruh pelayanan tatap muka secara mendadak', 'E. Pembebasan seluruh tarif pajak hotel tanpa kajian fiskal'], 1, 'RB Tematik = birokrasi diarahkan menyelesaikan masalah warga nyata (kemiskinan, investasi, digitalisasi berdampak, PDN/inflasi/stunting)!', 'RB Tematik menggeser orientasi Reformasi Birokrasi dari pemenuhan dokumen administrasi internal menuju dampak konkret bagi masyarakat.'],
    ['SAKIP, Reformasi Birokrasi & Zona Integritas', 'kbj-exp-zi-6-area-13', 'Dalam pembangunan Zona Integritas menuju WBK/WBBM (PermenPANRB 90/2021), enam area pengungkit yang wajib dibenahi instansi meliputi Manajemen Perubahan, Penataan Tata Laksana, Penataan SDM, Penguatan Akuntabilitas, Penguatan Pengawasan, dan...', ['A. Peningkatan Belanja Perjalanan Dinas', 'B. Peningkatan Kualitas Pelayanan Publik', 'C. Penambahan Jumlah Stiker Kantor', 'D. Pembatasan Informasi APBD ke Warga', 'E. Sentralisasi Honorarium Rapat'], 1, '6 Area Pengungkit ZI + 2 Hasil Akhir (Pemerintahan Bersih/Bebas KKN & Kualitas Pelayanan Publik Prima)!', 'Peningkatan Kualitas Pelayanan Publik merupakan area pengungkit ke-6 yang dibuktikan langsung lewat survei persepsi kepuasan masyarakat (IKM/SPAK).'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-mpp-integrasi-14', 'Kehadiran Mal Pelayanan Publik (MPP) di kabupaten/kota yang menggabungkan loket layanan Pemda, Polres (SIM/SKCK), Imigrasi, BPJS, dan KPP Pajak dalam satu atap bertujuan utama...', ['A. Memperpanjang rantai persetujuan berjenjang kepala dinas', 'B. Mengintegrasikan layanan lintas instansi secara cepat, transparan, dan memangkas biaya/waktu tempuh warga', 'C. Mengambil alih seluruh kewenangan pemerintah pusat menjadi aset daerah', 'D. Mewajibkan seluruh pemohon memakai calo resmi berizin', 'E. Menggantikan fungsi pengawasan DPRD terhadap bupati'], 1, 'MPP = one-stop integrated public service (Pusat + Daerah + BUMN/Swasta) satu pintu!', 'PermenPANRB tentang MPP mendorong konvergensi layanan publik terintegrasi dengan standar waktu dan biaya jelas serta dukungan MPP Digital.'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-oss-rba-risiko-15', 'Sistem Perizinan Berusaha Terintegrasi Secara Elektronik Berbasis Risiko (OSS-RBA, PP 5/2021) membagi kegiatan usaha menjadi risiko rendah, menengah rendah, menengah tinggi, dan tinggi. Untuk usaha berisiko RENDAH, pelaku UMKM cukup mengantongi...', ['A. Izin Lingkungan AMDAL lengkap + Izin Mendirikan Gedung bertingkat terlebih dahulu', 'B. Nomor Induk Berusaha (NIB) yang otomatis berlaku sekaligus sebagai identitas legalitas dan SNI/Pernyataan Mandiri', 'C. Persetujuan langsung Presiden sebelum membuka toko', 'D. Sertifikat Standar yang diverifikasi inspektorat selama 6 bulan', 'E. Surat rekomendasi 7 kepala dinas secara manual'], 1, 'OSS-RBA Risiko Rendah = cukup NIB (terbit cepat otomatis)! Tinggi = NIB + Izin + Verifikasi penuh!', 'PP 5/2021 menerapkan pendekatan berbasis tingkat risiko guna memangkas birokrasi bagi usaha mikro/risiko rendah lewat NIB tunggal.'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-spm-6-bidang-16', 'Sesuai Pasal 18 UU 23/2014 dan PP 2/2018, 6 urusan pemerintahan wajib yang berkaitan dengan Pelayanan Dasar dan memiliki Standar Pelayanan Minimal (SPM) oleh Pemda terdiri atas Pendidikan, Kesehatan, Pekerjaan Umum & Penataan Ruang, Perumahan Rakyat & Kawasan Permukiman, Ketenteraman Ketertiban & Perlindungan Masyarakat, serta...', ['A. Pariwisata dan Ekonomi Kreatif', 'B. Sosial', 'C. Perdagangan Ekspor-Impor', 'D. Pertambangan Mineral', 'E. Telekomunikasi Satelit'], 1, '6 Urusan SPM Wajib Dasar: Dik-Kes-PU-Perkim-Trantibumlinmas-SOSIAL!', 'SPM wajib diutamakan alokasi anggarannya dalam APBD sebelum membiayai belanja non-prioritas lainnya.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-gini-ratio-17', 'Koefisien Gini (Gini Ratio) digunakan perencana pembangunan untuk mengukur tingkat ketimpangan distribusi pendapatan/pengeluaran penduduk. Nilai Koefisien Gini = 0,48 dibanding tahun sebelumnya 0,36 mengindikasikan...', ['A. Distribusi pendapatan masyarakat semakin merata sempurna', 'B. Ketimpangan pengeluaran antar kelompok penduduk semakin melebar/memburuk', 'C. Tingkat kemiskinan absolut turun drastis menjadi nol', 'D. Seluruh penduduk memiliki jumlah tabungan identik', 'E. Laju inflasi daerah pasti berada di angka negatif'], 1, 'Gini 0 = merata sempurna; Gini 1 = ketimpangan ekstrem! Semakin mendekati 1 = makin timpang!', 'Batas ketimpangan rendah biasanya < 0,30; sedang 0,30–0,40; tinggi > 0,40 sehingga butuh intervensi fiskal/bansos pro-rakyat miskin.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-ipm-komponen-18', 'Indeks Pembangunan Manusia (IPM) metode baru BPS dibentuk dari tiga dimensi dasar yang diukur melalui empat indikator: Umur Harapan Hidup saat lahir, Harapan Lama Sekolah, Rata-rata Lama Sekolah, serta...', ['A. Jumlah gedung perguruan tinggi di ibu kota', 'B. Pengeluaran per kapita per tahun yang disesuaikan (PPP)', 'C. Panjang jalan tol di suatu provinsi', 'D. Total penerimaan pajak kendaraan bermotor', 'E. Persentase kepemilikan kartu kredit warga'], 1, '3 Dimensi IPM: Umur panjang/sehat (UHH), Pengetahuan (HLS & RLS), Standar hidup layak (Pengeluaran riil per kapita)!', 'Keempat komponen dihitung memakai rata-rata geometrik agar ketertinggalan satu dimensi tidak tertutup otomatis oleh dimensi lain.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-did-evaluasi-19', 'Untuk mengevaluasi dampak kausal sebuah program beasiswa/BLT daerah terhadap kenaikan angka kelulusan siswa dibanding kelompok kontrol yang tidak menerima bantuan sebelum-dan-sesudah program, metode ekonometrik evaluasi kebijakan paling kuat adalah...', ['A. Rata-rata sederhana nilai penerima pascaprogram tanpa kelompok pembanding', 'B. Difference-in-Differences (DiD) atau Propensity Score Matching (PSM) pada evaluasi kuasi-eksperimental', 'C. Polling opini spontan di grup pesan warga', 'D. Membaca brosur promosi program tahun sebelumnya', 'E. Menghitung jumlah panitia pelaksana acara'], 1, 'Evaluasi dampak kausal (counterfactual) memakai RCT atau kuasi-eksperimental DiD / PSM!', 'Difference-in-Differences membandingkan perubahan outcome kelompok perlakuan dan pembanding lintas waktu sehingga bias tren umum tersaring.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-icor-investasi-20', 'Jika suatu daerah memiliki Incremental Capital Output Ratio (ICOR) sebesar 7,5 sedangkan daerah lain memiliki ICOR 4,2, makna ekonominya bagi perencana kebijakan investasi adalah...', ['A. Daerah pertama jauh lebih efisien dalam mengubah investasi menjadi pertumbuhan PDB/PDRB', 'B. Daerah pertama membutuhkan modal investasi jauh lebih besar untuk menghasilkan tambahan 1 unit output ekonomi (kurang efisien dibanding 4,2)', 'C. Daerah kedua mengalami resesi ekonomi akibat investasi negatif', 'D. ICOR hanya mengukur jumlah pajak penghasilan badan', 'E. Angka ICOR lebih besar selalu berarti infrastruktur sempurna'], 1, 'ICOR = ΔInvestasi / ΔOutput PDRB! Semakin KECIL ICOR, semakin EFISIEN biaya investasi memacu pertumbuhan!', 'ICOR tinggi (mis. > 6) menandakan tingginya biaya ekonomi/logistik/perizinan sehingga butuh deregulasi OSS-RBA dan perbaikan infrastruktur konektivitas.'],
    ['Studi Kasus Kebijakan Publik & Tata Kelola', 'kbj-exp-kasus-stunting-21', 'Hasil audit kinerja menemukan anggaran stunting Rp18 miliar habis 96% tetapi angka prevalensi stunting hanya turun 0,2%. Sebagian besar belanja ternyata terserap untuk rapat hotel, honorarium tim, dan pengadaan seragam kader. Rekomendasi Policy Brief terbaik adalah...', ['A. Menaikkan honor kader 100% agar tahun depan serapan tetap tinggi', 'B. Mengaudit ulang Pohon Kinerja dan merealokasi >=70% anggaran ke intervensi spesifik & sensitif langsung kepada ibu hamil/baduta lokus DTSEN/EPPGBM', 'C. Menghentikan seluruh pendataan gizi di posyandu agar angka terlihat turun', 'D. Memindahkan seluruh anggaran stunting ke proyek gapura desa', 'E. Memberikan penghargaan kinerja terbaik karena serapan keuangan 96%'], 1, 'Pisahkan "output serapan kas" vs "outcome gizi anak": pastikan intervensi spesifik/sensitif menyentuh keluarga sasaran lokus!', 'Serapan kas tinggi untuk belanja penunjang justru merupakan pemborosan kebijakan (policy failure) bila lokus 1.000 HPK tidak menerima manfaat gizi dan sanitasi riil.'],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-klhs-lingkungan-22', 'Kajian Lingkungan Hidup Strategis (KLHS) wajib disusun dalam rancangan RPJMD dan RTRW guna memastikan...', ['A. Seluruh lahan pertanian boleh langsung dialihfungsikan menjadi mal tanpa kajian daya dukung', 'B. Prinsip pembangunan berkelanjutan dan daya dukung/daya tampung lingkungan terintegrasi ke dalam kebijakan rencana dan program', 'C. Harga tanah di kawasan lindung otomatis dinaikkan tiap semester', 'D. Dinas lingkungan hidup tidak lagi perlu mengawasi limbah industri', 'E. Proyek tambang bebas dari kewajiban reklamasi pascaoperasi'], 1, 'KLHS = instrumen hulu memastikan RPJMD/RTRW tidak melampaui daya dukung & daya tampung lingkungan!', 'Diatur dalam UU 32/2009 PPLH dan PP 46/2016: KLHS berada di level KRP (Kebijakan, Rencana, Program), lebih hulu dari AMDAL yang berada di level proyek.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-mcda-kriteria-23', 'Analis kebijakan membandingkan 3 opsi penyelesaian kemacetan kota memakai Multi-Criteria Decision Analysis (MCDA) dengan bobot Efektivitas 40%, Biaya Fiskal 25%, Ekuitas/Keadilan Sosial 20%, dan Kelayakan Politik-Hukum 15%. Opsi yang dipilih secara rasional adalah opsi dengan...', ['A. Biaya paling murah walaupun efektivitasnya hampir nol', 'B. Skor tertimbang total tertinggi lintas seluruh kriteria dengan mitigasi risiko terukur', 'C. Dukungan media sosial terbanyak tanpa menghitung anggaran', 'D. Waktu pengerjaan paling cepat 1 hari meskipun melanggar tata ruang', 'E. Jumlah konsultan eksternal terbanyak'], 1, 'MCDA menilai trade-off beberapa kriteria terukur secara objektif dengan pembobotan transparan!', 'MCDA mencegah pengambilan keputusan sepihak pada satu aspek (biasanya hanya biaya atau popularitas) dalam kebijakan publik kompleks.'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-sp4n-lapor-24', 'Dalam tata kelola pengaduan pelayanan publik nasional terintegrasi (SP4N-LAPOR!), laporan warga tentang pungutan liar di kantor layanan yang berstatus "terverifikasi" wajib diteruskan maksimal berapa hari kerja kepada instansi berwenang?', ['A. 3 hari kerja oleh pengelola pengaduan', 'B. 90 hari kerja setelah tahun anggaran berakhir', 'C. 180 hari menunggu sidang paripurna', 'D. Hanya bila laporan dikirim disertai akta notaris', 'E. Tidak perlu ditindaklanjuti jika pengadu memakai fitur anonim'], 0, 'SP4N-LAPOR! (PermenPANRB 62/2018): verifikasi & disposisi <= 3 hari kerja, tindak lanjut cepat & terukur!', 'Fitur Anonim dan Rahasia pada SP4N-LAPOR! melindungi pelapor agar pengawasan sosial masyarakat berjalan tanpa rasa takut intimidasi.'],
    ['Studi Kasus Kebijakan Publik & Tata Kelola', 'kbj-exp-kasus-banjir-hulu-25', 'Kota hilir rutin kebanjiran setiap musim hujan akibat alih fungsi hutan resapan di kabupaten tetangga di wilayah hulu. Pendekatan tata kelola kebijakan antardaerah yang paling efektif menurut UU 23/2014 adalah...', ['A. Kota hilir membangun tembok pembatas di perbatasan tanpa bicara dengan kabupaten hulu', 'B. Kerja Sama Antar Daerah (KAD) berdasar skema kompensasi jasa ekosistem hulu-hilir yang difasilitasi Pemerintah Provinsi', 'C. Menunggu anggaran darurat bencana setiap tahun sebagai pos rutin', 'D. Membubarkan dinas tata ruang di kedua daerah', 'E. Menggugat warga hilir agar pindah ke daerah lain secara sepihak'], 1, 'Eksternalitas lintas batas admin -> selesaikan lewat Kerja Sama Antar Daerah (PP 28/2018) & fasilitasi Gubernur selaku Wakil Pemerintah Pusat!', 'Banjir DAS adalah isu lintas batas yurisdiksi sehingga butuh kerja sama kawasan (hulu-hilir) dengan skema pendanaan jasa lingkungan dan sinkronisasi RTRW.'],
    ['SAKIP, Reformasi Birokrasi & Zona Integritas', 'kbj-exp-evaluasi-sakip-predikat-26', 'Pada hasil Evaluasi AKIP pemerintah daerah/kementerian, predikat nilai >= 80–90 dikategorikan "A" (Memuaskan), sedangkan nilai > 90–100 mendapat predikat tertinggi...', ['A. BBB', 'B. AA (Sangat Memuaskan)', 'C. CC', 'D. BB+', 'E. S+'], 1, 'Skala SAKIP KemenPANRB (PP 8/2006 & PermenPANRB 88/2021): AA (>90), A (>80-90), BB (>70-80), B (>60-70), CC (>50-60), C (>30-50), D (<=30)!', 'Predikat AA menandakan perencanaan, pengukuran kinerja individu hingga pimpinan, penganggaran, dan evaluasi internal sudah terintegrasi penuh ke budaya kerja berbasis hasil.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-dtsen-regsos-27', 'Mengapa sinkronisasi Data Tunggal Sosial Ekonomi Nasional (DTSEN / Regsosek) berbasis NIK dan geo-tagging sangat menentukan keberhasilan kebijakan perlindungan sosial pemerintah?', ['A. Supaya jumlah penerima bantuan bisa ditambah tak terbatas tanpa verifikasi', 'B. Menghilangkan inclusion error (warga mampu menerima) dan exclusion error (warga sangat miskin terlewat) sekaligus mempermudah pemadanan lintas bantuan', 'C. Agar pemerintah daerah tidak perlu melakukan pemutakhiran musyawarah desa/kelurahan', 'D. Supaya seluruh bantuan wajib diberikan dalam bentuk seragam kantor', 'E. Agar data warga dapat dijual ke platform pinjaman daring komersial'], 1, 'Target presisi bansos menekan DUATIKET error: Inclusion Error (orang kaya masuk) & Exclusion Error (orang miskin terlewat)!', 'Pemadanan dinamis DTSEN bersama Dukcapil dan pemutakhiran berkala desa/kelurahan membuat belanja perlindungan sosial tepat sasaran.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-nudge-behavior-28', 'Pemerintah kota mengganti formulir kepesertaan program pilah sampah rumah tangga dari opt-in (warga mendaftar aktif) menjadi opt-out otomatis dengan pengingat jadwal tagihan bersih, sehingga partisipasi naik 3 kali lipat tanpa denda paksa. Pendekatan kebijakan ini dikenal sebagai...', ['A. Command and Control dengan pidana penjara', 'B. Behavioral Insights / Nudge Policy (Arsitektur Pilihan)', 'C. Privatisasi total aset kota', 'D. Deregulasi anggaran penuh', 'E. Monopoli pasar terbuka'], 1, 'Nudge (Thaler & Sunstein) mengarahkan perilaku publik lebih baik lewat default & desain pilihan tanpa membatasi kebebasan!', 'Behavioral Public Policy sering jauh lebih murah dan efektif dibanding pengawasan sanksi denda konvensional pada perilaku warga sehari-hari.'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-iki-pelayanan-29', 'Unsur wajib yang harus dimuat dalam Standar Pelayanan Publik tiap unit layanan pemerintah berdasarkan UU No. 25 Tahun 2009 terdiri atas komponen service delivery dan komponen...', ['A. Campaign Marketing Eksternal', 'B. Manufacturing (pengelolaan internal layanan: dasar hukum, sarana, kompetensi pelaksana, pengawasan internal, jaminan keamanan)', 'C. Lobi Anggaran Parlemen', 'D. Iklan Komersial Swasta', 'E. Sanksi Politik Daerah'], 1, '14 Komponen Standar Pelayanan UU 25/2009 terbagi 2: 6 Service Delivery (dirasakan langsung warga) + 8 Manufacturing (back-office pengelola)!', 'Memisahkan Service Delivery dan Manufacturing membantu instansi memastikan janji waktu/biaya ke warga didukung kesiapan SOP, kompetensi SDM, dan keamanan internal.'],
    ['Studi Kasus Kebijakan Publik & Tata Kelola', 'kbj-exp-kasus-umkm-kredit-30', 'Studi evaluasi program bantuan modal UMKM Rp5 juta per usaha menunjukkan 40% usaha tutup kembali setelah 6 bulan. Temuan menunjukkan mereka kesulitan pencatatan kas, standarisasi kemasan PIRT/halal, dan akses pemasaran. Kebijakan lanjutan berbasis bukti paling tepat adalah...', ['A. Membagikan uang tunai dua kali lipat tanpa pendampingan agar usaha lebih besar', 'B. Mengubah desain menjadi paket terintegrasi pembiayaan + pendampingan inkubasi bisnis, fasilitasi NIB/Halal/PIRT, dan kurasi masuk e-Katalog/pasar digital', 'C. Mewajibkan pelaku usaha menyerahkan sertifikat tanah sebagai jaminan hibah', 'D. Menutup seluruh koperasi pembina karena dianggap gagal', 'E. Mengganti program bantuan usaha menjadi subsidi bahan bakar saja'], 1, 'Bantuan modal tanpa pendampingan pasar/legalitas berisiko tinggi gagal; ubah jadi ekosistem inkubasi + akses pasar!', 'Analisis akar masalah (Problem Tree) menunjukkan modal bukan kendala tunggal; integrasi legalitas usaha, kurasi, dan pemasaran digital (seperti e-Katalog lokal/P3DN) meningkatkan keberlanjutan UMKM.'],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-sinkron-ran-rak-31', 'Rencana Aksi Nasional (RAN) dan Rencana Aksi Daerah (RAD) untuk isu lintas sektor seperti SDGs atau Perubahan Iklim memiliki peran sebagai...', ['A. Pengganti kedudukan UUD 1945 di daerah otonom', 'B. Dokumen operasional penjabaran target sektoral terukur lintas instansi beserta indikator dan tenggat pelaksanaannya yang diarusutamakan ke RKP/RKPD', 'C. Laporan pertanggungjawaban kas harian bendahara', 'D. Dokumen rahasia internal yang tidak boleh diketahui Bappeda', 'E. Surat izin operasional bangunan bertingkat'], 1, 'RAN/RAD mengoordinasikan aksi multisektor dengan target, tahun, dan penanggung jawab jelas agar masuk ke RKPD/APBD!', 'Tanpa integrasi ke dokumen RKPD dan RKA, rencana aksi tematik hanya menjadi dokumen deklarasi tanpa alokasi anggaran riil.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-agenda-street-level-32', 'Dalam teori implementasi kebijakan (Michael Lipsky), kesenjangan antara maksud peraturan pusat yang baik dengan kenyataan berbeda saat dieksekusi di loket puskesmas atau kecamatan sering ditentukan oleh diskresi...', ['A. Dewan Pengawas Internasional', 'B. Street-Level Bureaucrats (birokrat garda depan pelaksana langsung seperti guru, petugas loket, perawat, polisi pamong)', 'C. Editor majalah berita mingguan', 'D. Vendor penyedia kertas fotokopi', 'E. Sekretaris jenderal organisasi luar negeri'], 1, 'Street-Level Bureaucrats berhadapan langsung dengan warga setiap hari — kapasitas & integritas merekalah penentu wajah kebijakan!', 'Itu sebabnya kebijakan baru wajib diikuti penyederhanaan SOP bagi petugas lapangan, insentif yang selaras, dan pelatihan praktis garda terdepan.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-sdi-satu-data-33', 'Dalam tata kelola Satu Data Indonesia (Perpres 39/2019) untuk mendukung perumusan kebijakan, peran pembina data statistik tingkat nasional serta wali data di pemerintah daerah secara berturut-turut dipegang oleh...', ['A. BPK dan DPRD', 'B. Badan Pusat Statistik (BPS) dan Dinas Komunikasi dan Informatika (Diskominfo) Daerah', 'C. Kementerian Keuangan dan Kejaksaan Negeri', 'D. ANRI dan Inspektorat Jenderal', 'E. BKN dan Sekretariat DPRD'], 1, 'Perpres 39/2019: Pembina Data Statistik = BPS; Data Geospasial = BIG; Data Keuangan = Kemenkeu; Wali Data Pemda = Diskominfo!', 'Satu Data memastikan standar data, metadata, kode referensi, dan interoperabilitas terpenuhi sebelum dipakai pengambilan keputusan di Bappenas/Bappeda.'],
    ['SAKIP, Reformasi Birokrasi & Zona Integritas', 'kbj-exp-rb-mal-integritas-34', 'Survei Penilaian Integritas (SPI) yang dijalankan KPK terhadap kementerian, lembaga, dan pemda mengukur tingkat risiko korupsi dari 3 sudut pandang responden utama yaitu...', ['A. Internal pegawai, eksternal pengguna layanan/mitra, dan eksper/narasumber ahli', 'B. Hanya kepala daerah dan sekretaris daerah saja', 'C. Pelajar sekolah menengah dan mahasiswa luar negeri', 'D. Konsultan iklan swasta saja', 'E. Hanya auditor eksternal saat pemeriksaan kas'], 0, 'SPI KPK 3 Pilar Responden: Internal + Eksternal (pengguna layanan/vendor) + Eksper -> cegah bias penilaian sendiri!', 'Indeks SPI membantu pimpinan mendeteksi area rawan suap/pengadaan/mutasi jabatan lebih dini sebelum terjadi OTT atau temuan kerugian negara.'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-blud-fleksibilitas-35', 'Mengapa RSUD dan Puskesmas di Pemda didorong menerapkan Pola Pengelolaan Keuangan Badan Layanan Umum Daerah (PPK-BLUD)?', ['A. Agar rumah sakit dapat menjadi PT swasta murni dan mengejar laba saham', 'B. Memberikan fleksibilitas pengelolaan keuangan langsung (pendapatan operasional dapat langsung dipakai membeli obat/alat mendesak sesuai RBA) sambil tetap tunduk pada akuntabilitas publik', 'C. Menghapus seluruh kewajiban menyusun laporan keuangan akrual pemerintah', 'D. Membebaskan RSUD dari tarif layanan maksimal warga miskin', 'E. Menghilangkan fungsi pengawasan Inspektorat Daerah'], 1, 'BLUD = "praktik bisnis sehat" nirlaba + fleksibilitas RBA mempercepat respon layanan publik kritis (obat/IGD)!', 'Tanpa BLUD, pendapatan layanan harus disetor ke kas daerah lebih dulu sehingga pengadaan obat darurat sering tersendat siklus DPA reguler.'],
    ['Studi Kasus Kebijakan Publik & Tata Kelola', 'kbj-exp-kasus-sampah-tpst-36', 'Kota berpenduduk 1 juta jiwa menghadapi TPA hampir penuh (overload dalam 1 tahun). Warga menolak pembukaan TPA baru di dekat permukiman (efek NIMBY). Kebijakan pengelolaan sampah jangka menengah yang komprehensif adalah...', ['A. Mengangkut sampah diam-diam pada malam hari ke perbatasan kota sebelah', 'B. Strategi hulu-hilir terpadu: kewajiban pilah sumber & bank sampah RT, TPST RDF/kompos di tingkat kawasan sehingga residu ke TPA tinggal <20%, disertai skema BLUD/retribusi adil', 'C. Membakar seluruh sampah secara terbuka di halaman kantor dinas lingkungan', 'D. Melarang masyarakat berbelanja barang berkemasan sama sekali mulai besok', 'E. Menunggu hingga TPA penuh lalu menyatakan status darurat selamanya'], 1, 'Atasi efek NIMBY dengan pengurangan sampah dari hulu (pilah + RDF/TPST kawasan) sehingga TPA bukan lagi tumpukan terbuka!', 'Pendekatan ekonomi sirkular (RDF untuk industri semen/PLTU, maggot BSF organik, bank sampah) memangkas drastis volume residu ke TPA.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-policy-termination-37', 'Evaluasi tahunan mendapati terdapat 38 aplikasi layanan daerah yang saling tumpang tindih dengan hanya < 5 pengguna aktif per bulan namun tetap menyedot biaya sewa server tahunan. Keputusan paling rasional dalam tahap akhir siklus kebijakan adalah...', ['A. Terus mendanai pemeliharaan ke-38 aplikasi agar aset tidak terlihat berkurang', 'B. Melakukan Policy Termination/Konsolidasi menghentikan aplikasi usang dan memigrasikan datanya ke satu Portal Layanan Terpadu SPBE', 'C. Mengubah warna tampilan logo ke-38 aplikasi supaya terlihat baru', 'D. Memaksa setiap warga mengunduh minimal 10 aplikasi berbeda saat mengurus KTP', 'E. Menyembunyikan statistik kunjungan server dari rapat evaluasi'], 1, 'Policy Termination/Consolidation menghentikan program/aplikasi tak efektif guna menghemat anggaran publik!', 'Perpres SPBE mendorong moratorium aplikasi baru terpecah dan konsolidasi menuju layanan publik digital terpadu.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-nls-kemiskinan-bps-38', 'Dalam metodologi BPS, indikator "Indeks Kedalaman Kemiskinan (P1)" dan "Indeks Keparahan Kemiskinan (P2)" lebih informatif daripada sekadar persentase jumlah penduduk miskin (P0) karena P1 dan P2 mampu menggambarkan...', ['A. Jumlah pegawai dinas sosial di tingkat kecamatan', 'B. Seberapa jauh rata-rata pengeluaran penduduk miskin berada di bawah Garis Kemiskinan (P1) dan tingkat ketimpangan di antara sesama penduduk miskin (P2)', 'C. Tingkat kelulusan ujian masuk perguruan tinggi negeri', 'D. Total nilai ekspor tambang provinsi', 'E. Rata-rata suhu udara tahunan wilayah miskin'], 1, 'P0 = headcount (berapa %), P1 = jarak kedalaman ke Garis Kemiskinan, P2 = keparahan/ketimpangan antarwarga miskin!', 'Jika program hanya menolong kelompok "hampir miskin", P0 bisa turun tetapi P1/P2 kaum miskin ekstrem tetap stagnan — wajib jadi perhatian Analis Kebijakan!'],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-renstra-renja-39', 'Hubungan hierarkis antara RPJMD/RKPD milik Pemerintah Daerah secara keseluruhan dengan dokumen perencanaan internal tiap Dinas/OPD adalah...', ['A. RPJMD diterjemahkan tiap OPD menjadi Renstra-PD (5 tahunan), sedangkan RKPD dijabarkan menjadi Renja-PD (tahunan)', 'B. Renstra-PD disusun lebih tinggi derajat hukumnya di atas RPJMD dan RPJMN', 'C. Renja-PD berlaku 20 tahun tanpa memperhatikan RKPD', 'D. OPD tidak perlu memiliki Renstra selama sudah ada kwitansi belanja', 'E. RKPD disusun oleh pihak swasta lalu disahkan dinas terkait'], 0, 'Level Daerah: RPJPD (20) -> RPJMD (5) -> RKPD (1). Level Dinas/PD: Renstra-PD (5) -> Renja-PD (1)!', 'Keselarasan antara RPJMD–Renstra PD serta RKPD–Renja PD menjamin sinkronisasi tujuan kepala daerah hingga kegiatan operasional setiap dinas.'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-ombudsman-maladm-40', 'Berdasarkan UU No. 37 Tahun 2008 dan UU Pelayanan Publik, tindakan penundaan berlarut tanpa kepastian, penyimpangan prosedur, atau tidak memberikan pelayanan oleh aparatur publik digolongkan Ombudsman RI sebagai...', ['A. Diskresi Sah Tanpa Catatan', 'B. Maladministrasi Pelayanan Publik yang wajib dikoreksi (LAHP / Tindakan Korektif)', 'C. Prestasi Inovasi Daerah', 'D. Hak Prerogatif Kepala Seksi', 'E. Perselisihan Perdata Swasta Murni'], 1, 'Penundaan berlarut, penyimpangan prosedur, pungli, berpihak = bentuk khas Maladministrasi yang diawasi Ombudsman!', 'Kepatuhan instansi menindaklanjuti saran Ombudsman turut menentukan predikat Opini Pengawasan Pelayanan Publik zona hijau.'],
    ['Studi Kasus Kebijakan Publik & Tata Kelola', 'kbj-exp-kasus-desa-dana-41', 'Sebuah pemerintah kabupaten ingin mempercepat penurunan kemiskinan ekstrem pedesaan lewat Dana Desa dan ADD, namun desa-desa tetap dominan membangun gapura dan paving jalan gang setiap tahun. Instrumen kebijakan paling tepat di tingkat kabupaten adalah...', ['A. Menghapus seluruh transfer Dana Desa untuk selamanya', 'B. Memperbaiki Peraturan Bupati tentang pedoman prioritas penggunaan ADD/Dana Desa disertai pendampingan penyusunan RPJMDes/RKPDes berbasis data keluarga miskin ekstrem dan insentif kinerja desa berdampak', 'C. Membiarkan pemerintah desa bebas sepenuhnya tanpa evaluasi kecamatan', 'D. Menyita langsung fisik gapura yang sudah jadi', 'E. Memerintahkan camat mengganti kepala desa di luar mekanisme hukum'], 1, 'Arahkan prioritas regulasi Bupati + insentif berbasis kinerja (reward desa berprestasi atasi kemiskinan/stunting) + pendampingan musdes!', 'Kebijakan fiskal berbasis insentif kinerja terbukti lebih efektif mengarahkan perilaku anggaran desa daripada sekadar imbauan lisan.'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-sunset-clause-42', 'Penyisipan "Sunset Clause" (klausul masa berlaku berakhir otomatis) pada Peraturan Menteri atau Perda stimulus pajak darurat pascabencana berfungsi strategis untuk...', ['A. Menjadikan fasilitas bebas pajak berlaku selamanya tanpa evaluasi', 'B. Mewajibkan evaluasi efektivitas kebijakan pada tanggal berakhir tertentu sehingga aturan tidak menumpuk menjadi regulasi usang', 'C. Membebaskan pemerintah dari keharusan mengumumkan peraturan ke publik', 'D. Menutup akses DPRD membahas perubahan aturan', 'E. Menghapus pengawasan BPK selama masa darurat'], 1, 'Sunset clause = mekanisme "kedaluwarsa otomatis" agar regulasi darurat tidak berubah menjadi beban permanen!', 'Praktik regulasi modern (good regulatory practice OECD) menggunakan sunset clause untuk mencegah penumpukan aturan kedaluwarsa.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-lagging-leading-ind-43', 'Dalam pemantauan kebijakan ketenagakerjaan, persentase pertumbuhan pendaftar izin usaha baru NIB dan pengajuan proyek industri kuartal ini disebut "Leading Indicator", sedangkan Tingkat Pengangguran Terbuka (TPT) tahunan berperan sebagai...', ['A. Indikator Input Belanja Kantor', 'B. Lagging Indicator (mengonfirmasi dampak hasil akhir setelah proses berjalan)', 'C. Variabel Pengganggu Acak', 'D. Indikator Anggaran Perjalanan', 'E. Syarat Administratif Kepegawaian'], 1, 'Leading = sinyal dini mengantisipasi arah depan; Lagging = hasil akhir terukur setelah kebijakan berdampak!', 'Analis Kebijakan menggabungkan Leading dan Lagging Indicator agar koreksi kebijakan bisa dilakukan lebih cepat sebelum krisis lapangan membesar.'],
    ['SAKIP, Reformasi Birokrasi & Zona Integritas', 'kbj-exp-keterpaduan-smart-44', 'Indikator kinerja "Meningkatkan kesejahteraan petani di Kabupaten A tahun depan" dinilai lemah dalam formulasi SMART karena tidak memenuhi unsur...', ['A. Ambiguous dan subjektif', 'B. Measurable (terukur angkanya seperti % kenaikan NTP/pendapatan) dan spesifik targetnya', 'C. Terlalu banyak angka dan satuan ukur', 'D. Menggunakan istilah bahasa Indonesia baku', 'E. Berhubungan dengan dinas pertanian'], 1, 'SMART: Specific, Measurable (angka/satuan target jelas), Achievable, Relevant, Time-bound!', 'Frasa umum seperti "meningkatkan kesejahteraan" wajib diturunkan ke metrik terukur (misal: Kenaikan Nilai Tukar Petani menjadi >= 108 pada tahun X).'],
    ['Pelayanan Publik, OSS-RBA & Tata Kelola Pemda', 'kbj-exp-govtech-interoperabilitas-45', 'Sesuai kebijakan transformasi GovTech Indonesia dan Arsitektur SPBE Nasional, masalah utama ribuan aplikasi layanan publik di kementerian/pemda yang terpisah-pisah diselesaikan dengan...', ['A. Membuat aplikasi portal baru di tiap seksi kantor setiap tahun', 'B. Interoperabilitas pertukaran data lewat Sistem Penghubung Layanan Pemerintah (SPLP), Portal Nasional terpadu, dan Single Sign-On', 'C. Mencetak ulang semua PDF menjadi dokumen fisik arsip', 'D. Mengharuskan warga mengingat 30 akun password terpisah', 'E. Mengganti semua komputer pegawai setiap triwulan'], 1, 'Kunci SPBE/GovTech: SPLP (pertukaran data), satu identitas digital terintegrasi, dan berpusat pada kebutuhan warga (human-centric)!', 'Dengan interoperabilitas SPLP, warga tidak perlu mengunggah KTP/KK berulang kali ke puluhan aplikasi berbeda ("Once Only Principle").'],
    ['Studi Kasus Kebijakan Publik & Tata Kelola', 'kbj-exp-kasus-transportasi-46', 'Pemerintah kota menyediakan bus kota bersubsidi (Buy The Service), namun okupansinya masih rendah (<30%) di jam kerja karena jarak halte terlalu jauh dari permukiman dan jadwal datang tidak menentu. Intervensi kebijakan berbasis bukti terbaik...', ['A. Menghentikan seluruh subsidi bus dan membiarkan warga kembali memakai motor pribadi', 'B. Menambah rute pengumpan (feeder mikrotrans) ke kawasan padat penduduk, menerapkan jadwal real-time GPS di halte/app, serta menata integrasi parkir-jalan', 'C. Menaikkan tarif bus 200% supaya terlihat eksklusif', 'D. Mewajibkan pelajar berjalan kaki 5 km setiap pagi', 'E. Mengubah seluruh bus menjadi kendaraan dinas pejabat'], 1, 'Analisis hambatan pengguna nyata (first-mile/last-mile & kepastian waktu) -> perbaiki konektivitas feeder & keandalan jadwal!', 'Subsidi angkutan umum gagal tanpa penyelesaian masalah akses pengumpan (first-mile/last-mile) dan kepastian waktu tunggu penumpang.'],
    ['Statistik Kebijakan, Data Pembangunan & Riset', 'kbj-exp-inflasi-ihk-tpid-47', 'Saat laporan BPS bulanan menunjukkan komoditas cabai merah, beras, dan bawang menyumbang andil inflasi tertinggi di suatu daerah, intervensi jangka pendek-menengah Tim Pengendalian Inflasi Daerah (TPID) berdasar kerangka 4K adalah...', ['A. Memblokir seluruh pasar tradisional agar masyarakat berhenti memasak', 'B. Keterjangkauan harga (operasi pasar), Ketersediaan pasokan (Kerja Sama Daerah surplus-defisit & cadangan pangan), Kelancaran distribusi, dan Komunikasi efektif ekspektasi pasar', 'C. Menetapkan harga jual eceran di bawah ongkos tanam petani tanpa subsidi angkut', 'D. Melarang warga melaporkan kenaikan harga ke media', 'E. Menaikkan tarif pajak restoran mendadak 50%'], 1, 'Strategi TPID BI + Kemenko + Pemda = 4K: Keterjangkauan harga, Ketersediaan pasokan, Kelancaran distribusi, Komunikasi efektif!', 'Kerja Sama Antardaerah (KAD) menghubungkan kabupaten surplus panen dengan kota konsumen defisit sembari menekan biaya logistik (subsidi ongkos angkut).'],
    ['Siklus & Analisis Kebijakan Publik', 'kbj-exp-cost-effectiveness-cea-48', 'Pada bidang kesehatan atau pendidikan di mana manfaatnya sulit dinilai murni dalam rupiah (seperti nyawa terselamatkan atau penurunan angka kematian bayi/AKI), metode evaluasi ekonomi kebijakan yang lebih tepat dibanding Cost-Benefit Analysis (CBA) murni adalah...', ['A. Cost-Effectiveness Analysis (CEA) — membandingkan biaya per unit hasil non-moneter seperti biaya per nyawa/QALY terselamatkan', 'B. Analisis Laba Bersih Saham Perusahaan Terbatas', 'C. Penghitungan Bunga Majemuk Perbankan', 'D. Lelang Penawaran Harga Terendah Konstruksi Baja', 'E. Survei Kepopuleran Logo Program'], 0, 'CBA: Biaya & Manfaat sama-sama Rp. CEA: Biaya Rp vs Manfaat outcome non-moneter (nyawa, penurunan stunting)!', 'CEA sangat lazim digunakan Analis Kebijakan sektor sosial, kesehatan, dan pendidikan guna mencari program berdampak maksimal per rupiah anggaran.'],
    ['SPPN & Dokumen Perencanaan (UU 25/2004)', 'kbj-exp-musrenbang-dewan-pokir-49', 'Pokok-pokok Pikiran (Pokir) DPRD dalam penyusunan RKPD daerah tetap dapat diakomodasi secara sah apabila...', ['A. Disisipkan mendadak saat DPA sudah berjalan tanpa verifikasi OPD', 'B. Diinput sebelum tenggat penyusunan RKPD lewat SIPD, selaras dengan prioritas RPJMD, memiliki verifikasi kelayakan teknis OPD, dan bebas konflik kepentingan pribadi', 'C. Berupa usulan pengadaan barang langsung ke rumah pribadi anggota', 'D. Mengabaikan pagu kemampuan keuangan APBD secara keseluruhan', 'E. Tidak perlu memiliki lokasi dan penerima manfaat yang jelas'], 1, 'Pokir sah = pendekatan politis yang tetap wajib diverifikasi keselarasan RPJMD + kelayakan teknis OPD + masuk SIPD tepat waktu!', 'Dalam Permendagri 86/2017, masukan Pokir adalah bagian proses demokratis yang wajib disaring secara teknokratik agar tetap akuntabel.'],
    ['Studi Kasus Kebijakan Publik & Tata Kelola', 'kbj-exp-kasus-izin-tata-ruang-50', 'Investor manufaktur ramah lingkungan berminat membangun pabrik padat karya di kabupaten dengan serapan 2.000 pekerja lokal, namun lahan yang diajukan ternyata masuk Lahan Pertanian Pangan Berkelanjutan (LP2B) yang dilindungi Perda RTRW. Keputusan Analis Kebijakan Tata Kelola yang tepat adalah...', ['A. Langsung menerbitkan izin bangun di atas lahan LP2B demi mengejar realisasi investasi cepat', 'B. Menolak lokasi LP2B tersebut sesuai RTRW sambil proaktif memfasilitasi pemetaan ulang/relokasi ke zona kawasan industri resmi yang tersedia dalam RDTR melalui layanan MPP/OSS', 'C. Membiarkan pabrik dibangun terlebih dahulu lalu mengubah RTRW bertahun-tahun kemudian secara diam-diam', 'D. Meminta investor membeli langsung lahan tanpa proses KKPR/OSS', 'E. Membekukan seluruh investasi di kabupaten selama 5 tahun'], 1, 'Jangan korbankan perlindungan pangan/hukum RTRW; beri solusi alternatif zona industri sah via RDTR/KKPR di OSS!', 'Penegakan RTRW + KKPR wajib bagi ketertiban hukum dan ketahanan pangan, sementara fasilitasi opsi zona industri menjaga iklim investasi daerah.']
  ];

  /* ==================== 2. SKB SDMA, ARSIPARIS & HUMAS (+50 Soal -> Total 105 Soal) ==================== */
  const SDMA_EXP = [
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-abk-siasn-01', 'Berdasarkan skema perhitungan ABK (PermenPANRB 1/2020) di bawah, jika sebuah unit mengurus 6.250 berkas layanan izin per tahun (norma waktu penyelesaian 1 jam per berkas) dengan standar jam kerja efektif 1.250 jam/tahun dan pegawai eksisting saat ini berjumlah 3 orang, berapa tambahan formasi ideal yang dibutuhkan?', [
      'A. 1 orang (total kebutuhan 4 orang)',
      'B. 2 orang (total kebutuhan 5 orang)',
      'C. 3 orang (total kebutuhan 6 orang)',
      'D. 5 orang (total kebutuhan 8 orang)',
      'E. Tidak ada kekurangan pegawai'
    ], 1, 'Kebutuhan = (6.250 × 1) ÷ 1.250 = 5 pegawai. Bezetting (eksisting) = 3 -> Kurang = 5 - 3 = 2 orang!', 'Perhitungan ABK objektif: (Volume Beban Kerja × Norma Waktu) ÷ Jam Kerja Efektif (1.250 jam/thn). Selisih kebutuhan minus bezetting menjadi dasar usulan formasi SIASN.', SVG_ABK_SIASN],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-uu20-prinsip-merit-02', 'Berdasarkan UU No. 20 Tahun 2023 tentang ASN, manajemen kepegawaian (pengangkatan, mutasi, promosi, dan penghargaan) wajib berlandaskan Sistem Merit, yakni keputusan kepegawaian yang didasarkan pada...', ['A. Senioritas usia, kedekatan daerah asal, dan rekomendasi politik', 'B. Kualifikasi, kompetensi, potensi, dan kinerja secara adil tanpa diskriminasi SARA/gender/afiliasi politik', 'C. Hasil voting tertutup rekan satu ruangan', 'D. Kesamaan almamater perguruan tinggi', 'E. Masa tunggu daftar hadir harian semata'], 1, 'Sistem Merit = Kualifikasi + Kompetensi + Kinerja secara objektif dan nondiskriminatif!', 'UU 20/2023 menegaskan penguatan budaya meritokrasi digital lewat manajemen talenta di seluruh instansi pusat maupun daerah.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-pppk-paruhwaktu-03', 'Salah satu terobosan krusial dalam UU No. 20 Tahun 2023 mengenai jenis pegawai ASN serta penyelesaian penataan tenaga non-ASN adalah...', ['A. Seluruh pegawai non-ASN langsung diberhentikan tanpa solusi pada hari pertama UU terbit', 'B. Pegawai ASN terdiri atas PNS dan PPPK, dengan penataan non-ASN diselesaikan melalui mekanisme seleksi PPPK (termasuk opsi skema penuh waktu dan paruh waktu sesuai kebutuhan & fiskal)', 'C. Menghapus seluruh status PPPK menjadi pegawai kontrak vendor swasta tanpa NIP', 'D. Mengangkat seluruh tenaga non-ASN secara otomatis menjadi Pejabat Eselon II', 'E. Melarang Pemda memiliki PPPK guru dan tenaga kesehatan'], 1, 'UU 20/2023: ASN = PNS & PPPK; penataan non-ASN via verifikasi BKN & skema PPPK penuh/paruh waktu tanpa PHK massal!', 'Pengaturan ini memastikan kepastian status hukum pegawai sekaligus menghentikan praktik rekrutmen honorer non-prosedural di instansi pemerintah.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-hak-cuti-pppk-04', 'Dalam ketentuan manajemen ASN, perbedaan hak jaminan hari tua dan pensiun antara PNS dengan PPPK dalam UU ASN 20/2023 diarahkan menuju sistem...', ['A. PPPK tidak berhak atas perlindungan JKK, JKM, serta jaminan kesehatan sama sekali', 'B. Kedua unsur ASN (PNS & PPPK) berhak memperoleh penghargaan dan pengakuan berimbang termasuk jaminan sosial (JKK, JKM, Jaminan Kesehatan, dan Jaminan Pensiun/Hari Tua berbasis skema iuran pasti)', 'C. Hanya PNS pusat yang berhak cuti tahunan, sedangkan PPPK dan Pemda dilarang cuti', 'D. PPPK wajib mengundurkan diri tiap 1 Januari setiap tahun', 'E. PNS tidak pernah memiliki jaminan hari tua sejak 2024'], 1, 'UU 20/2023 menyetarakan kerangka penghargaan & pengakuan ASN termasuk jaminan sosial berbasis skema sesuai PP turunan!', 'Pasal 21 UU 20/2023 menyusun konsep penghargaan & pengakuan ASN komprehensif agar PPPK memiliki kepastian jaminan sosial dan hari tua.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-bup-jabatan-05', 'Batas Usia Pensiun (BUP) standar menurut UU ASN bagi Pejabat Administrasi, Fungsional Ahli Pertama & Muda, serta Fungsional Ahli Utama secara berturut-turut adalah...', ['A. 55, 58, dan 60 tahun', 'B. 58 tahun (Administrasi & Ahli Muda/Pertama), 60 tahun (Pimpinan Tinggi & Ahli Madya), dan 65 tahun (Fungsional Ahli Utama)', 'C. Semuanya sama rata 62 tahun', 'D. 50, 55, dan 58 tahun', 'E. 60 tahun untuk pelaksana dan 58 tahun untuk Pimpinan Tinggi'], 1, 'Ingat tangga BUP ASN: 58 (Pelaksana/Adm/JF Pertama-Muda) -> 60 (JPT/JF Madya) -> 65 (JF Utama)!', 'Untuk jabatan fungsional tertentu seperti Guru Besar/Peneliti Utama memiliki ketentuan BUP lebih tinggi sesuai UU sektoral masing-masing.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-talenta-9box-06', 'Dalam Manajemen Talenta ASN (PermenPANRB 3/2020), metode "9-Box Talent Grid" memetakan pegawai berdasarkan dua sumbu utama penilaian yaitu...', ['A. Usia kerja vs golongan pangkat semata', 'B. Sumbu Potensi/Kompetensi vs Sumbu Kinerja guna menentukan Kader Suksesor (Box 9: Kinerja Tinggi & Potensi Tinggi)', 'C. Besaran tunjangan kinerja vs jumlah anak pegawai', 'D. Jarak rumah ke kantor vs jumlah absensi sidik jari', 'E. Lama menjabat eselon vs asal universitas'], 1, '9-Box Matrix = Potensi (X/Y) × Kinerja! Kotak puncak (Box 9) masuk Rencana Suksesi JPT!', 'Rencana suksesi berbasis 9-Box mempercepat pengisian jabatan strategis secara objektif tanpa seleksi ulang yang memakan waktu lama saat terjadi kekosongan.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-evajab-fess-07', 'Dalam Evaluasi Jabatan (PermenPANRB 34/2011) menggunakan Factor Evaluation System (FES) untuk menentukan Kelas Jabatan (Job Grade) penentu tunjangan kinerja, terdapat berapa faktor evaluasi utama pada jabatan fungsional/pelaksana vs jabatan struktural?', ['A. 9 faktor untuk Fungsional/Pelaksana (pengetahuan, pengawasan, pedoman, kompleksitas, ruang lingkup, hubungan personal, tujuan hubungan, persyaratan fisik, lingkungan kerja) dan 6 faktor untuk Struktural', 'B. Hanya 1 faktor yaitu masa kerja tahunan', 'C. 2 faktor yaitu tinggi badan dan warna kulit', 'D. 15 faktor khusus keuangan bank', 'E. Ditentukan acak oleh bendahara gaji tanpa informasi faktor jabatan'], 0, 'FES Evajab = 9 Faktor Jabatan Fungsional/Pelaksana & 6 Faktor Jabatan Struktural -> menghasilkan Total Poin -> Kelas Jabatan (Grade)!', 'Evaluasi jabatan menentukan keadilan kompensasi (Equal Pay for Work of Equal Value) di kementerian maupun Pemda.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-skp-ekinerja-08', 'Menurut PermenPANRB No. 6 Tahun 2022 tentang Pengelolaan Kinerja Pegawai ASN, Predikat Kinerja Pegawai "Sangat Baik", "Baik", "Butuh Perbaikan", "Kurang", dan "Sangat Kurang" diperoleh dari...', ['A. Nilai rata-rata ujian pilihan ganda tahunan saja', 'B. Kuadran persilangan antara Rating Hasil Kerja (ekspektasi kinerja) dan Rating Perilaku Kerja (BerAKHLAK)', 'C. Daftar hadir sidik jari tanpa melihat output pekerjaan', 'D. Penilaian subyektif rekan sejawat tanpa dialog kinerja', 'E. Lama pegawai lembur di akhir pekan'], 1, 'SKP PermenPANRB 6/2022 = Matrix Hasil Kerja (Di Atas/Sesuai/Di Bawah Ekspektasi) × Perilaku Kerja BerAKHLAK!', 'Dialog kinerja berkelanjutan antara atasan (Pejabat Penilai) dan pegawai serta umpan balik berkala menjadi inti siklus SKP di aplikasi e-Kinerja BKN.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-jf-perm1-2023-09', 'Perubahan mendasar pembinaan Jabatan Fungsional sejak PermenPANRB No. 1 Tahun 2023 dibanding aturan lama (butir kegiatan DUPAK) adalah...', ['A. Pejabat fungsional tidak lagi dinilai kinerjanya sepanjang tahun', 'B. Penghapusan DUPAK berbasis pengumpulan kredit per butir kegiatan kaku, diganti dengan konversi langsung Predikat Kinerja tahunan (e-Kinerja) menjadi Angka Kredit', 'C. Kenaikan pangkat jabatan fungsional hanya boleh 1 kali seumur hidup', 'D. Seluruh jabatan fungsional otomatis dihapus dan diubah menjadi staf tata usaha', 'E. Angka kredit dihitung dari jumlah sertifikat seminar daring berbayar saja'], 1, 'PermenPANRB 1/2023: Bye DUPAK ribet! Predikat SKP tahunan ("Baik" = 100% koefisien AK tahunan, "Sangat Baik" = 150%) langsung dikonversi ke Angka Kredit!', 'Transformasi ini membuat pejabat fungsional (Prakom, Analis, Guru, Dokter, Auditor) fokus pada capaian prioritas organisasi bukan sibuk memberkas DUPAK administratif.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-uji-kompetensi-upkom-10', 'Jika seorang Pejabat Fungsional Ahli Pertama telah memenuhi syarat Angka Kredit kumulatif untuk naik jenjang ke Ahli Muda, namun belum terdapat lowongan formasi kebutuhan jenjang Ahli Muda pada Peta Jabatan unit kerja dan belum lulus Uji Kompetensi, langkah kepegawaian yang sah adalah...', ['A. Tetap dilantik ke Ahli Muda meski tanpa formasi maupun uji kompetensi', 'B. Belum dapat naik jenjang; kenaikan jenjang JF mensyaratkan AK kumulatif terpenuhi, tersedianya kebutuhan lowongan formasi pada Peta Jabatan, dan lulus Uji Kompetensi', 'C. Mengajukan kenaikan jenjang paksa melalui pengadilan negeri', 'D. Meminta rekan satu ruangan mengundurkan diri agar ada formasi', 'E. Mengganti nama jabatannya sendiri di tanda tangan surat dinas'], 1, '3 Syarat Naik Jenjang JF: 1) AK Kumulatif cukup, 2) Ada Kebutuhan Formasi Peta Jabatan, 3) Lulus Uji Kompetensi!', 'Aturan ini mencegah penumpukan pejabat ahli madya/utama tanpa beban kerja riil sesuai peta jabatan ABK.'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-disiplin-pp94-bolos-11', 'Berdasarkan PP No. 94 Tahun 2021 tentang Disiplin PNS, apabila seorang PNS tidak masuk kerja secara akumulatif tanpa alasan sah selama 28 hari kerja atau lebih secara berturut-turut selama 10 hari kerja terus-menerus dalam 1 tahun, hukuman disiplin yang dijatuhkan adalah...', ['A. Teguran lisan dari kepala seksi saja', 'B. Pemberhentian dengan hormat tidak atas permintaan sendiri (hukuman disiplin berat)', 'C. Pemotongan cuti tahunan 1 hari saja', 'D. Penundaan jam istirahat makan siang', 'E. Tidak ada sanksi bila mengganti di hari Sabtu tanpa izin'], 1, 'Angka emas PP 94/2021: Mangkir >= 10 hari BERTURUT-TURUT ATAU >= 28 hari KUMULATIF dalam setahun = Hukuman Disiplin Berat Pemberhentian!', 'Sementara mangkir 3 hari = teguran lisan, 4–6 hari = teguran tertulis, 7–10 hari = pernyataan tidak puas secara tertulis (disiplin ringan).'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-netralitas-pemilu-12', 'Tindakan ASN menjelang Pemilu/Pilkada yang tergolong PELANGGARAN netralitas ASN menurut SKB 5 Kementerian/Lembaga dan UU 20/2023 adalah...', ['A. Menggunakan hak pilih di bilik suara TPS secara rahasia pada hari pemungutan suara', 'B. Memberikan tanda "like", komentar dukungan, foto berpose simbol jari tertentu bersama bakal calon kepala daerah di media sosial', 'C. Menghadiri sosialisasi penyelenggara pemilu KPU sebagai petugas pendata warga netral', 'D. Menjelaskan regulasi jadwal cuti kampanye secara objektif ke staf', 'E. Membaca visi-misi para kandidat dari portal berita resmi sebagai pemilih'], 1, 'ASN wajib netral total di dunia fisik MAUPUN medsos (nol like/share/pose simbol kampanye)!', 'Pelanggaran netralitas ASN berdampak hukuman disiplin sedang hingga berat dan merusak kepercayaan publik terhadap birokrasi pelayanan.'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-mutasi-pilkada-13', 'Larangan bagi Kepala Daerah (Gubernur/Bupati/Wali Kota) melakukan penggantian/mutasi pejabat di lingkungan Pemda selama jangka waktu 6 bulan sebelum tanggal penetapan pasangan calon sampai dengan akhir masa jabatan, kecuali mendapat...', ['A. Persetujuan tertulis dari Menteri Dalam Negeri (dengan pertimbangan teknis BKN sesuai sistem merit)', 'B. Rekomendasi ketua RT setempat', 'C. Persetujuan lisan penyedia jasa katering kantor', 'D. Hasil polling media sosial', 'E. Surat pengantar bendahara pengeluaran'], 0, 'Pasal 71 UU Pilkada: mutasi 6 bulan sebelum penetapan paslon s.d. selesai masa jabatan DILARANG tanpa izin tertulis Mendagri + Pertek BKN!', 'Aturan ini melindungi ASN Pemda dari politisasi birokrasi menjelang kontestasi pemilihan kepala daerah.'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-cuti-pp11-17-14', 'Seorang PNS wanita melahirkan anak keempat berhak mengajukan cuti... dengan ketentuan penghasilan sesuai PP 11/2017 jo PP 17/2020 berupa...', ['A. Cuti melahirkan 3 bulan untuk anak ke-1 s.d. ke-3; sedangkan untuk anak ke-4 dst diberikan Cuti Besar (bukan cuti melahirkan reguler, tetap mempertahankan penghasilan pokok tanpa tunjangan jabatan jika cuti besar penuh)', 'B. Dilarang mengambil cuti sama sekali dan otomatis diberhentikan', 'C. Cuti di luar tanggungan negara selama 5 tahun wajib', 'D. Cuti tahunan dipotong sampai minus 30 hari', 'E. Wajib mutasi ke unit non-fungsional selama 1 tahun'], 0, 'Cuti Melahirkan = anak 1 s.d. 3 (3 bulan). Anak ke-4 dst = Cuti Besar!', 'Pengetahuan detail jenis cuti PNS (Tahunan 12 hari, Besar 3 bln syarat 5 thn kerja, Sakit, Melahirkan, Alasan Penting max 1 bln, Bersama, Di Luar Tanggungan Negara).'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-siasn-pertek-15', 'Penggunaan layanan terintegrasi SIASN oleh BKD/BKPSDM dan Biro SDM Kementerian memberikan manfaat strategis bagi manajemen ASN nasional berupa...', ['A. Kenaikan pangkat, penetapan NIP, mutasi, dan pensiun diproses digital end-to-end dengan Pertimbangan Teknis (Pertek) BKN yang transparan, paperless, dan cepat', 'B. Menghapus seluruh catatan kinerja pegawai dari negara', 'C. Mengizinkan pegawai mengedit pangkat golongannya sendiri sesuka hati', 'D. Menggantikan fungsi Kementerian Keuangan mencairkan gaji pokok', 'E. Melarang pertukaran data antar-Pemda seluruh Indonesia'], 0, 'SIASN BKN + MyASN = single source of truth kepegawaian ASN terintegrasi dari rekrutmen, Pertek KP/Mutasi, e-Kinerja, hingga Pensiun!', 'Keberadaan MyASN juga memampukan setiap ASN mengawasi pemutakhiran data profil, SKP, dan riwayat diklat pribadinya secara mandiri.'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-srikandi-4pilar-16', 'Dalam penerapan Aplikasi Umum Bidang Kearsipan Dinamis (SRIKANDI) sesuai Perpres SPBE dan peraturan ANRI, 4 instrumen kearsipan pilar yang wajib ditetapkan tiap kementerian/Pemda terlebih dahulu sebelum memakai sistem adalah...', ['A. Tata Naskah Dinas (TND), Klasifikasi Arsip, Jadwal Retensi Arsip (JRA), dan Sistem Klasifikasi Keamanan & Akses Arsip Dinamis (SKKAAD)', 'B. Kuitansi Belanja, Daftar Hadir, Foto Rapat, dan Surat Tugas', 'C. Harga Perkiraan Sendiri, Kontrak, BAST, dan SPM', 'D. Peta Jabatan, ABK, SKP, dan DUPAK', 'E. SKCPNS, NPWP, BPJS, dan KTP'], 0, '4 Pilar Kearsipan Instansi: TND + Klasifikasi Arsip + JRA + SKKAAD!', 'Keempat instrumen menjadi fondasi klasifikasi surat masuk-keluar, hak akses rahasia/terbatas, dan masa simpan-musnah otomatis di SRIKANDI.'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-arsip-vital-terjaga-17', 'Perbedaan mendasar antara Arsip Vital dengan Arsip Terjaga dalam UU No. 43 Tahun 2009 tentang Kearsipan adalah...', ['A. Arsip Vital berkaitan dengan keberlangsungan operasional dasar instansi pencipta (sertifikat aset, kontrak krusial, data kependudukan); sedangkan Arsip Terjaga berkaitan dengan keberadaan dan kelangsungan hidup bangsa/negara (batas wilayah, perjanjian internasional, kontrak karya strategis) yang salinan autentiknya wajib diserahkan ke ANRI', 'B. Arsip Vital boleh dimusnahkan tiap 6 bulan, sedangkan Arsip Terjaga dijual umum', 'C. Keduanya adalah dokumen koran harian di ruang lobi kantor', 'D. Arsip Terjaga hanya milik perusahaan swasta, bukan negara', 'E. Arsip Vital wajib dibakar setiap pergantian tahun anggaran'], 0, 'Vital = nyawa operasional instansi (aset/hak hukum); Terjaga = kedaulatan & nyawa NKRI (wajib serah salinan autentik ke ANRI <= 1 tahun setelah dibuat)!', 'Penyelamatan Arsip Vital meliputi penyimpanan ruang tahan api/banjir, duplikasi, dan alih media terenkripsi off-site.'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-penyusutan-jra-18', 'Tiga bentuk penyusutan arsip yang sah menurut UU Kearsipan (UU 43/2009) berdasarkan Jadwal Retensi Arsip (JRA) dilakukan melalui...', ['A. Pemindahan arsip inaktif dari unit pengolah ke unit kearsipan (Records Center), pemusnahan arsip yang tidak bernilai guna sesuai prosedur, serta penyerahan arsip statis bernilai guna sejarah ke Lembaga Kearsipan (ANRI/LKD)', 'B. Penjualan kertas ke pengepul swasta sesuka staf tanpa berita acara', 'C. Penghapusan langsung di komputer tanpa persetujuan kepala dinas', 'D. Penyimpanan selamanya seluruh brosur rapat di gudang basah', 'E. Pembakaran massal di lapangan kantor setiap Jumat'], 0, '3 Jalan Penyusutan Arsip Sah: Pemindahan (Aktif -> Inaktif) + Pemusnahan (tanpa nilai guna, harus berita acara & persetujuan JRA/ANRI) + Penyerahan (Statis ke ANRI/LKD)!', 'Memusnahkan arsip negara tanpa prosedur sah (mis. arsip keuangan/aset belum habis retensi atau tanpa panitia penilai) diancam sanksi pidana Pasal 81–86 UU 43/2009!'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-alih-media-autentikasi-19', 'Ketika arsip kertas asli hasil audit 5 tahun lalu dialihmediakan ke format digital PDF/A, apa syarat hukum agar arsip digital alih media tersebut diakui sah sebagai alat bukti hukum (PP 28/2012 & UU ITE)?', ['A. Cukup difoto memakai kamera ponsel lalu dikirim lewat WhatsApp pribadi', 'B. Diautentikasi oleh pimpinan instansi pencipta arsip (disertai berita acara alih media, tanda tangan elektronik/segel, dan metadata autentikasi lengkap)', 'C. Diubah isi teksnya agar tampak lebih rapi di layar komputer', 'D. Disimpan di akun penyimpanan cloud pribadi pegawai tanpa catatan indeks', 'E. Dokumen kertas langsung dibuang pada detik yang sama sebelum berita acara dibuat'], 1, 'Alih Media Sah = Berita Acara + Daftar Arsip + Autentikasi Pimpinan/TTE sesuai PP 28/2012!', 'Untuk arsip statis atau bernilai sejarah tinggi, dokumen fisik aslinya tetap dipelihara meskipun sudah dialihmediakan menjadi kopi digital layanan.'],
    ['Kehumasan Pemerintah, Protokol & Keterbukaan Informasi', 'sdma-exp-uu-kip-4kategori-20', 'Dalam UU No. 14 Tahun 2008 tentang Keterbukaan Informasi Publik (KIP) yang dikelola Pejabat Pengelola Informasi dan Dokumentasi (PPID), informasi mengenai SOP layanan publik, tarif PNBP, serta laporan keuangan audited termasuk kategori informasi yang...', ['A. Dikecualikan secara mutlak sepanjang zaman', 'B. Wajib Disediakan dan Diumumkan Secara Berkala atau Serta Merta (terbuka proaktif tanpa harus diminta warga)', 'C. Hanya boleh dibuka jika warga membayar biaya sewa ruang pengadilan', 'D. Rahasia negara kelas satu yang hanya diketahui dua pejabat', 'E. Boleh dirahasiakan selama masih ada sengketa internal staf'], 1, '4 Kategori UU KIP: Berkala (SOP, LK, anggaran), Serta Merta (bencana/wabah), Tersedia Setiap Saat (daftar informasi, kontrak umum), Dikecualikan (uji konsekuensi ketat)!', 'PPID wajib melakukan Uji Konsekuensi tertulis bila hendak mengecualikan suatu informasi (mis. data pribadi NIK/medis warga sesuai UU PDP atau strategi penyidikan aktif).'],
    ['Kehumasan Pemerintah, Protokol & Keterbukaan Informasi', 'sdma-exp-keprotokolan-uu9-21', 'Berdasarkan UU No. 9 Tahun 2010 tentang Keprotokolan, tata tempat, tata upacara, dan tata penghormatan merupakan tiga ruang lingkup pengaturan protokol resmi negara. Bila Presiden/Menteri hadir bersama Gubernur pada acara kenegaraan di provinsi, prinsip dasar Tata Tempat menempatkan Pejabat Negara sesuai...', ['A. Urutan abjad nama depan para pejabat', 'B. Preseance (urutan kedudukan kenegaraan, pemerintahan, dan tingkat keterwakilan wilayah/tuan rumah, posisi paling kanan sebelah utama lebih terhormat)', 'C. Siapa yang lebih dulu tiba di ruang VIP acara', 'D. Tinggi badan para tamu undangan', 'E. Urutan kursi acak panitia penyelenggara'], 1, 'Tata Tempat Protokol (UU 9/2010): Hormati Preseance! Tempat terhormat di sebelah KANAN tamu utama/tengah ganjil!', 'Pengaturan tata tempat dan urutan penyampaian sambutan yang keliru pada acara kementerian/Pemda sering memicu insiden diplomatik/kelembagaan serius.'],
    ['Kehumasan Pemerintah, Protokol & Keterbukaan Informasi', 'sdma-exp-krisis-humas-gpr-22', 'Saat terjadi insiden kebocoran data atau gangguan layanan berat di instansi pemerintah dan isu negatif meluas cepat di media sosial, prinsip Komunikasi Krisis Humas Pemerintah (GPR) pada "Golden Hour" pertama adalah...', ['A. Menonaktifkan kolom komentar semua media sosial dan menolak wawancara pers selama 14 hari', 'B. Segera mengaktifkan juru bicara satu pintu, mengakui peristiwa secara jujur berdasar fakta terverifikasi, menyampaikan empati + langkah mitigasi nyata warga terdampak, dan pembaruan berkala', 'C. Menyalahkan pihak vendor atau masyarakat karena tidak membaca panduan', 'D. Mengalihkan perhatian dengan mengunggah konten hiburan kantor tanpa klarifikasi', 'E. Menyebarkan data pribadi pelapor pertama ke publik agar jera'], 1, 'Golden Hour Krisis Humas = Cepat, Empatik, Transparan berbasis fakta (bukan denial/defensif), Satu Suara Juru Bicara + Aksi Korektif!', 'Menghindar/bungkam saat krisis membuat ruang informasi segera diisi spekulasi dan hoaks yang jauh lebih merusak reputasi pemerintah.'],
    ['Studi Kasus SDM Aparatur, Konflik Kerja & Kearsipan', 'sdma-exp-kasus-gap-kompetensi-23', 'Hasil asesmen SDM instansi menunjukkan 65% pegawai pengelola pengadaan belum memiliki kompetensi teknis pengadaan elektronik serta nilai integritas kasus rendah, sementara unit tidak punya anggaran diklat klasikal hotel. Solusi Learning & Development paling efektif dan hemat sesuai konsep Pengembangan Kompetensi Terintegrasi (Corporate University / 70:20:10) adalah...', ['A. Menunda seluruh pengadaan selama 2 tahun sampai ada anggaran hotel bintang lima', 'B. Menerapkan porsi 70% pembelajaran di tempat kerja (on-the-job coaching & proyek kerja terpandu), 20% mentoring/peer learning dari senior ahli, dan 10% e-learning/MOOC LMS terkurasi dengan konversi minimal 20 JP/tahun', 'C. Membeli sertifikat pelatihan daring massal tanpa ujian praktik', 'D. Memindahkan semua staf tersebut ke bagian keamanan gedung sekaligus', 'E. Mewajibkan staf menyewa konsultan pribadi pakai dana pribadi'], 1, 'Corpu ASN & Model 70:20:10 (LAN/PermenPANRB Bangkom): 70% praktik kerja + 20% coaching/mentoring + 10% kursus kelas/MOOC!', 'Sesuai UU 20/2023 dan peraturan LAN, hak pengembangan kompetensi ASN bukan hanya seminar hotel, melainkan ekosistem belajar terintegrasi minimal >= 20 JP/tahun.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-talenta-karier-batas-24', 'Seorang Analis SDM Ahli Madya di Pemda berprestasi tinggi ingin mengikuti seleksi terbuka Jabatan Pimpinan Tinggi Pratama (Eselon II) di suatu kementerian pusat. Prinsip mobilitas talenta ASN lintas instansi dalam UU ASN 20/2023 memungkinkan hal tersebut selama...', ['A. Pegawai tersebut mengundurkan diri sebagai PNS terlebih dahulu dan mengulang tes CPNS dari awal', 'B. Memenuhi kualifikasi/syarat kompetensi JPT, lolos seleksi terbuka/manajemen talenta, serta memperoleh persetujuan pindah instansi sesuai ketentuan merit nasional', 'C. Ia merupakan kerabat dekat panitia seleksi instansi tujuan', 'D. Pemda asal tidak pernah menggunakan sistem informasi SIASN', 'E. Pegawai baru bekerja 6 bulan sebagai CPNS'], 1, 'Talenta Nasional UU 20/2023 mendorong mobilitas talenta lintas pusat-daerah berbasis merit (asal memenuhi syarat jenjang, kompetensi & prosedur)!', 'Mobilitas talenta bertujuan mendistribusikan SDM unggul nasional secara merata ke pusat maupun daerah 3T tanpa sekat ego kewilayahan.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-peta-jabatan-komposisi-25', 'Fungsi Peta Jabatan dalam organisasi kementerian maupun Pemda yang ditetapkan pejabat pembina kepegawaian adalah...', ['A. Daftar denah tempat parkir pejabat eselon di halaman kantor', 'B. Gambaran susunan seluruh jabatan struktural, fungsional, dan pelaksana dalam setiap unit kerja lengkap dengan kelas jabatan, bezetting saat ini, dan kebutuhan ABK-nya', 'C. Peta lokasi geografis kantor kecamatan di wilayah kabupaten', 'D. Jadwal piket kebersihan mingguan pegawai kontrak', 'E. Tabel pembagian jatah kue rapat unit'], 1, 'Peta Jabatan = blueprint kebutuhan & formasi SDM tiap unit kerja (Nama Jabatan + Kelas Jabatan + Bezetting + Kebutuhan ABK)!', 'Tanpa Peta Jabatan dan Anjab-ABK yang sah dari KemenPANRB/Mendagri, pengangkatan maupun rekrutmen CPNS/PPPK tidak dapat diproses pada e-Formasi.'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-hukuman-jenjang-pp94-26', 'Manakah pengelompokan tingkat hukuman disiplin PNS dalam PP No. 94 Tahun 2021 yang benar dari jenis sanksi di bawah ini?', ['A. Ringan: Teguran lisan/tertulis/tidak puas; Sedang: Pemotongan tunjangan kinerja 25% selama 6, 9, atau 12 bulan; Berat: Penurunan jabatan setingkat lebih rendah 12 bln, Pembebasan dari jabatan menjadi pelaksana 12 bln, atau Pemberhentian dengan hormat tidak atas permintaan sendiri', 'B. Ringan: Pemberhentian tidak hormat; Sedang: Teguran lisan; Berat: Potong tukin 5%', 'C. Ringan: Penurunan pangkat 3 tahun; Sedang: Teguran lisan; Berat: Denda parkir', 'D. Seluruh hukuman disiplin berupa teguran lisan saja sejak 2021', 'E. Hukuman sedang adalah mutasi otomatis ke kementerian lain'], 0, 'Update besar PP 94/2021 (pengganti PP 53/2010): Hukuman SEDANG fokus pemotongan TUKIN 25% (6/9/12 bln), BUKAN lagi penundaan KGB/KP!', 'Perubahan krusial PP 94/2021 sangat sering keluar di tes SDMA: penundaan KGB/KP dihapus, diganti pemotongan Tukin 25% untuk hukuman disiplin sedang.'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-skkaad-klasifikasi-27', 'Dalam pengamanan arsip dinamis (SKKAAD — Sistem Klasifikasi Keamanan dan Akses Arsip Dinamis), berkas hasil pemeriksaan psikologi pelamar ASN serta rekam medis individu harus diklasifikasikan sebagai...', ['A. Biasa / Terbuka untuk seluruh internet tanpa sensor', 'B. Terbatas / Rahasia — hanya diakses pejabat berwenang atau pemilik data guna melindungi privasi dan UU Pelindungan Data Pribadi', 'C. Boleh dibagikan langsung di grup chat umum sebagai bahan candaan', 'D. Arsip niaga publik tanpa batas waktu', 'E. Dokumen publik otomatis pada portal terbuka daerah'], 1, 'SKKAAD membagi 4 tingkat: Biasa/Terbuka, Terbatas, Rahasia, Sangat Rahasia — jaga privasi & UU PDP 27/2022!', 'Kebocoran data rekam medis/NIK kepegawaian akibat kesalahan hak akses melanggar baik UU Kearsipan, UU KIP pengecualian privasi, maupun UU PDP.'],
    ['Kehumasan Pemerintah, Protokol & Keterbukaan Informasi', 'sdma-exp-survey-ikm-km14-28', 'Dalam penyusunan Survei Kepuasan Masyarakat (SKM) instansi pemerintah sesuai PermenPANRB No. 14 Tahun 2017 yang wajib dipublikasikan oleh Humas/unit layanan, jumlah unsur penilaian baku dan hasil akhirnya dikonversi dalam skala nilai mutu...', ['A. 3 unsur nilai dengan skala maksimal 10', 'B. 9 unsur pelayanan (Persyaratan, Sistem/Mekanisme/Prosedur, Waktu, Biaya/Tarif, Produk Spesifikasi, Kompetensi Pelaksana, Perilaku Pelaksana, Penanganan Pengaduan, Sarana Prasarana) dengan skala interval 25–100 (Sangat Baik >= 88,31)', 'C. 20 unsur penilaian dengan nilai akhir huruf A sampai Z', 'D. Hanya unsur tarif biaya saja tanpa melihat perilaku petugas', 'E. Dilakukan 10 tahun sekali jika diminta LSM'], 1, 'PermenPANRB 14/2017 SKM = 9 Unsur Pelayanan -> Indeks Konversi maks 100 ("A / Sangat Baik" >= 88,31)!', 'Publikasi IKM serta tindak lanjut perbaikan dari unsur bernilai terendah wajib dipajang transparan di ruang layanan dan laman resmi instansi.'],
    ['Studi Kasus SDM Aparatur, Konflik Kerja & Kearsipan', 'sdma-exp-kasus-salah-tmt-pensiun-29', 'Biro SDM mendapati 12 pegawai hampir memasuki BUP dalam 6 bulan namun belum pernah mengusulkan berkas pensiun tepat waktu, sementara terdapat juga pegawai tidak mengajukan kenaikan pangkat reguler karena data gelar di MyASN belum sinkron. Langkah perbaikan sistemik Analis SDMA adalah...', ['A. Menunggu pegawai tersebut sadar sendiri datang membawa map fisik H-1 pensiun', 'B. Mengaktifkan dasbor peringatan otomatis proaktif (early warning 12 & 6 bulan pra-BUP/KP) di SIASN, memfasilitasi pemutakhiran data PDM mandiri MyASN berkala, dan menerbitkan SLA layanan SDM kurang dari 14 hari', 'C. Menunda gaji pegawai bersangkutan hingga map diantar', 'D. Meminta pegawai pensiun mengetik sendiri SK Pertek BKN-nya', 'E. Menghapus daftar tanggal lahir pegawai dari sistem SDM'], 1, 'Ubah tata kelola SDM dari "reaktif tunggu berkas fisik" -> "proaktif otomatis via alert SIASN + MyASN"!', 'Digitalisasi layanan kepegawaian menuntut HR proaktif (early warning BUP/KP/KGB) supaya hak kepegawaian tidak tertunda akibat kelalaian administrasi.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-corevalues-berakhlak-30', 'Standar Nilai Dasar ASN (Core Values) "BerAKHLAK" beserta Employer Branding "Bangga Melayani Bangsa" (SE MenPANRB 20/2021 & UU 20/2023) mencakup tujuh nilai inti yaitu...', ['A. Berorientasi Pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, Kolaboratif', 'B. Bersaing, Aktif, Konsumtif, Hebat, Lincah, Aman, Kreatif', 'C. Berani, Agresif, Kaku, Hierarkis, Lengkap, Adil, Konservatif', 'D. Berwibawa, Ambisius, Komersial, Handal, Luwes, Aset, Konsisten', 'E. Bersama, Abadi, Kuat, Hormat, Luhur, Asri, Kompak'], 0, 'BerAKHLAK = Berorientasi Pelayanan · Akuntabel · Kompeten · Harmonis · Loyal · Adaptif · Kolaboratif!', 'Setiap penilaian perilaku kerja dalam SKP e-Kinerja dan wawancara seleksi ASN berpatokan langsung pada panduan perilaku tujuh nilai BerAKHLAK.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-anjab-uraiantugas-31', 'Hasil Analisis Jabatan (Anjab) yang tertuang dalam dokumen Informasi Jabatan (Infojab) memuat identitas jabatan, ikhtisar jabatan, uraian tugas, bahan kerja, perangkat kerja, hasil kerja, serta...', ['A. Besaran pinjaman kredit pegawai di bank daerah', 'B. Syarat jabatan (pendidikan, diklat, pengalaman kerja, pangkat) beserta hubungan kerja dan kondisi lingkungan kerja', 'C. Daftar menu makan siang karyawan', 'D. Alamat rumah orang tua pejabat terkait', 'E. Riwayat suara partai politik di kecamatan'], 1, 'Anjab melahirkan Infojab (apa pekerjaannya & syarat kompetensi yang dibutuhkan -> masuk ke seleksi & evaluasi jabatan)!', 'Ketajaman Infojab menentukan apakah rekrutmen CPNS/PPPK memanggil kualifikasi jurusan pendidikan yang tepat atau meleset.'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-tubel-ijinbelajar-32', 'Kebijakan Tugas Belajar ASN terkini (SE MenPANRB 28/2021) menyederhanakan konsep lama Tugas Belajar vs Izin Belajar menjadi skema tunggal "Tugas Belajar" yang dapat dilaksanakan baik...', ['A. Hanya berhenti bekerja total menggunakan anggaran negara saja', 'B. Dengan dibebaskan dari tugas jabatan ATAU tetap melaksanakan tugas jabatan (biaya APBN/APBD maupun biaya mandiri selama terakreditasi & sesuai kebutuhan organisasi)', 'C. Secara diam-diam tanpa izin PPK sampai wisuda baru mengajukan pencantuman gelar', 'D. Hanya di luar negeri tanpa syarat akreditasi program studi', 'E. Khusus pejabat eselon I tanpa perlu persetujuan unit SDM'], 1, 'SE MenPANRB 28/2021: Hanya ada Tugas Belajar (Diberhentikan dari jabatan vs Tidak diberhentikan / kuliah di luar jam kerja tetap butuh SK Tubel sebelum kuliah)!', 'PNS yang berkuliah diam-diam tanpa SK Tugas Belajar resmi terancam penolakan pencantuman gelar di SIASN BKN!'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-arsip-naskah-klasifikasi-33', 'Pengkodean nomor surat dinas menggunakan Klasifikasi Arsip berbasis fungsi fasilitatif (seperti Kepegawaian KP, Keuangan KU, Hukum HK) maupun fungsi substantif instansi dimaksudkan agar...', ['A. Surat terlihat panjang dan sulit dibaca penerima', 'B. Pengelompokan berkas, pemberkasan aktif, pencarian kembali (retrieval time < 1 menit), dan penetapan masa retensi penyusutan seragam dan akurat', 'C. Menggantikan fungsi stempel tanda tangan pejabat', 'D. Setiap bidang membuat nomor kode rahasia sendiri sesuka staf', 'E. Menghambat transfer dokumen antardinas daerah'], 1, 'Klasifikasi Arsip (PermenANRI) menyusun arsip secara tematis-hierarkis agar temu balik kilat dan retensi JRA presisi!', 'Pemberkasan yang tertib berbasis klasifikasi menjaga keutuhan seri berkas (filing system) bukan sekadar menumpuk map kronologis acak.'],
    ['Kehumasan Pemerintah, Protokol & Keterbukaan Informasi', 'sdma-exp-pranata-humas-agenda-34', 'Dalam tugas Jabatan Fungsional Pranata Hubungan Masyarakat, pemantauan media massa & media sosial (media monitoring) serta analisis sentimen isu publik bermanfaat langsung bagi pimpinan untuk...', ['A. Mengunci seluruh akun berita daring swasta', 'B. Menyusun Early Warning Isu Publik, evaluasi persepsi kebijakan, dan strategi pesan komunikasi pemerintah berbasis bukti', 'C. Menentukan kenaikan tarif pajak restoran harian', 'D. Memilih warna cat tembok kantor dinas', 'E. Menggantikan laporan keuangan akrual tahunan'], 1, 'Media monitoring & analisis sentimen = kompas pimpinan memahami respons publik & menangkal disinformasi secara proaktif!', 'Pranata Humas modern bertindak sebagai penasihat komunikasi strategis pimpinan, bukan sekadar fotografer acara seremonial.'],
    ['Studi Kasus SDM Aparatur, Konflik Kerja & Kearsipan', 'sdma-exp-kasus-plagiarism-spip-35', 'Saat meneliti kelengkapan berkas arsip kepegawaian pegawai lama untuk persiapan pengisian Jabatan Pengawas, Arsiparis menemukan dua ijazah berindikasi kejanggalan akreditasi saat tahun terbit serta SK pangkat fisik hilang akibat banjir lama. Langkah akuntabel yang sah adalah...', ['A. Menerbitkan ijazah pengganti di komputer kantor agar berkas lengkap', 'B. Mengonfirmasi keaslian riwayat akademik ke Pangkalan Data Pendidikan Tinggi (PDDikti), meminta Salinan Resmi/Pencarian Arsip di Kantor Regional BKN/ANRI, serta berkoordinasi dengan Inspektorat jika terbukti ijazah palsu', 'C. Mengabaikan kejanggalan ijazah karena pegawai tersebut dekat dengan atasan', 'D. Memusnahkan sisa berkas banjir tanpa berita acara', 'E. Menandatangani sendiri surat keterangan lulus'], 1, 'Verifikasi silang PDDikti + Kanreg BKN + eskalasi Inspektorat untuk dugaan pemalsuan dokumen ASN!', 'Integritas data kepegawaian dan arsip kepegawaian wajib sah secara hukum guna mencegah pelanggaran disiplin berat dan temuan audit.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-pppk-kompensasi-kinerja-36', 'Apabila dalam satu tahun anggaran seorang pegawai (PNS maupun PPPK) mendapat Predikat Kinerja "Kurang" atau "Sangat Kurang", manajemen kinerja menurut PP 30/2019 & PermenPANRB 6/2022 memberi mekanisme pembinaan berupa...', ['A. Otomatis langsung dipecat pada hari pertama tanpa kesempatan pembinaan', 'B. Coaching kinerja wajib selama paling lama 6 bulan untuk perbaikan; bila tetap tidak membaik dapat dikenai sanksi disiplin / pemutusan hubungan perjanjian kerja PPPK sesuai aturan', 'C. Diberi tambahan bonus tunjangan 50% sebagai penyemangat', 'D. Dipromosikan ke jabatan lebih tinggi agar berubah suasananya', 'E. Dibiarkan saja tanpa ada umpan balik apa pun'], 1, 'Kinerja Kurang -> Bimbingan Kinerja (Coaching max 6 bln) -> Evaluasi Ulang -> Sanksi/Pemutusan perjanjian kerja bila gagal!', 'Kinerja PPPK dievaluasi per tahun dan menjadi syarat utama perpanjangan masa perjanjian kerja maupun pemberian kenaikan gaji berkala.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-pelatihan-kluster-kompetensi-37', 'Standar Kompetensi Jabatan (SKJ) ASN (PermenPANRB 38/2017) membagi kompetensi pegawai ke dalam tiga rumpun utama yang diuji saat seleksi maupun asesmen pengembangan karier yaitu...', ['A. Kompetensi Teknis, Kompetensi Manajerial (8 aspek), dan Kompetensi Sosial Kultural (Perekat Bangsa)', 'B. Kompetensi Finansial Pribadi, Kompetensi Politik Partai, dan Hobi Pribadi', 'C. Kompetensi Atletik, Kompetensi Musik, dan Seni Rupa', 'D. Kompetensi Mengetik cepat dan Fotokopi saja', 'E. Kompetensi Bahasa Asing Kuno semata'], 0, '3 Rumpun SKJ ASN = Teknis (profesi) + Manajerial (8 poin: Integritas..Mengelola Perubahan..Keputusan) + Sosiokultural (Perekat Bangsa)!', 'Pada CAT SKD-SKB dan Assessment Center BKN, pemetaan kamus kompetensi SKJ menjadi standar objektif kesesuaian orang dengan jabatan (Person-Job Fit).'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-lhkpn-lhkasn-siharka-38', 'Kewajiban penyampaian laporan harta kekayaan bagi pejabat negara dan penyelenggara negara tertentu serta aparatur sipil negara (seperti JPT, PPK pengadaan, auditor, pejabat keuangan) disalurkan melalui sistem...', ['A. LHKPN KPK (untuk wajib lapor tertentu) dan pelaporan kekayaan ASN / SPT Tahunan pajak terintegrasi sesuai ketentuan instansi', 'B. Unggahan story media sosial pribadi sekali dalam sepuluh tahun', 'C. Buku tamu keamanan gedung depan', 'D. Formulir kupon undian koperasi pegawai', 'E. Tidak ada kewajiban laporan harta bagi pejabat daerah'], 0, 'Transparansi harta LHKPN KPK + SPT Pajak + pelaporan internal ASN mencegah konflik kepentingan dan TPPU!', 'Kepatuhan LHKPN juga menjadi komponen indikator Zona Integritas dan syarat mengikuti seleksi terbuka JPT.'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-indeks-kearsipan-anri-39', 'Penilaian Pengawasan Kearsipan Nasional oleh ANRI menilai dua aspek pengawasan di setiap Kementerian/Lembaga dan Pemda yaitu pengawasan internal (pengelolaan arsip dinamis tiap unit kerja) dan pengawasan...', ['A. Eksternal atas penyelenggaraan kearsipan termasuk pengelolaan arsip statis, SDM arsiparis, prasarana, serta penerapan aplikasi SRIKANDI', 'B. Harga pembelian printer baru setiap bulan', 'C. Jumlah tamu yang datang ke perpustakaan umum', 'D. Tingkat kecerahan warna kertas HVS', 'E. Lama waktu rapat staf tanpa notulen'], 0, 'Audit Kearsipan ANRI (eksternal & internal) menilai kepatuhan arsip dinamis, statis, SDM arsiparis, depo penyimpanan, serta implementasi SRIKANDI!', 'Skor Audit Kearsipan menjadi komponen penting dalam penilaian Reformasi Birokrasi nasional sebuah instansi.'],
    ['Kehumasan Pemerintah, Protokol & Keterbukaan Informasi', 'sdma-exp-sengketa-kip-komisi-40', 'Jika pemohon informasi publik ditolak permintaan datanya oleh PPID instansi tanpa dasar Uji Konsekuensi yang meyakinkan atau tidak ditanggapi melewati batas waktu (10 + 7 hari kerja), langkah hukum yang dapat ditempuh pemohon secara resmi adalah...', ['A. Mengajukan keberatan ke Atasan PPID, lalu jika tetap tidak selesai mengajukan penyelesaian sengketa informasi ke Komisi Informasi (KI)', 'B. Langsung meretas situs instansi agar data terunduh sendiri', 'C. Menyebarkan data pribadi petugas loket PPID ke forum daring', 'D. Mengajukan kasasi pidana langsung ke Mahkamah Konstitusi', 'E. Membayar oknum keamanan untuk meminjam brankas dokumen'], 0, 'Alur Sengketa KIP (UU 14/2008): PPID (10+7 hr) -> Keberatan ke Atasan PPID (30 hr) -> Sengketa ke Komisi Informasi (Mediasi/Ajudikasi)!', 'Pemahaman SLA waktu layanan UU KIP sangat krusial agar instansi terhindar dari kalah dalam sidang ajudikasi di Komisi Informasi.'],
    ['Studi Kasus SDM Aparatur, Konflik Kerja & Kearsipan', 'sdma-exp-kasus-rotasi-stagnan-41', 'Sebuah unit pelayanan memiliki staf pelaksana berkinerja cemerlang yang sudah 9 tahun di posisi sama tanpa promosi dan mulai mengalami kejenuhan (burnout), sementara posisi fungsional sejalur terbuka lowongan di instansi tersebut. Tindakan Analis SDM yang tepat adalah...', ['A. Membiarkannya di meja yang sama hingga pensiun supaya unit lama tidak perlu melatih pengganti', 'B. Mengarahkan pemetaan karier ke Jabatan Fungsional melalui skema perpindahan dari jabatan lain (uji kompetensi + syarat formasi ABK) dan merancang rotasi pengayaan tugas', 'C. Memotong tunjangan kinerjanya agar kembali bersemangat', 'D. Memindahkannya secara paksa ke bagian gudang tanpa pemberitahuan', 'E. Menjanjikan jabatan kepala dinas tanpa melewati seleksi'], 1, 'Cegah career plateau lewat jalur karier JF (perpindahan jabatan lain), rotasi pengayaan kompetensi, dan pembinaan karier transparan!', 'Pengembangan karier jelas menjaga retensi talenta terbaik ASN agar tidak demotivasi di birokrasi.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-penghargaan-satyalancana-42', 'Selain gaji dan tunjangan, negara memberikan tanda kehormatan kesetiaan pengabdian berupa Satyalancana Karya Satya kepada PNS yang telah bekerja penuh secara terus-menerus tanpa catatan hukuman disiplin berat/sedang masing-masing pada masa kerja...', ['A. 5, 15, dan 25 tahun', 'B. 10 tahun (perunggu), 20 tahun (perak), dan 30 tahun (emas)', 'C. 2, 4, dan 6 tahun', 'D. 12, 24, dan 36 tahun', 'E. Hanya diberikan setelah meninggal dunia'], 1, 'Satyalancana Karya Satya = 10, 20, 30 tahun pengabdian setia tanpa cacat disiplin!', 'Penghargaan non-materiel ini memperkuat loyalitas, kebanggaan profesi, serta rekam jejak moralitas aparatur negara.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-cascading-skp-bawahan-43', 'Saat menyusun Matriks Pembagian Peran dan Hasil (MPH) pada e-Kinerja di awal tahun, Rencana Hasil Kerja (RHK) seorang staf ahli pertama harus diturunkan langsung dari...', ['A. Keinginan pribadi staf tentang proyek hobi yang disukainya', 'B. Rencana Hasil Kerja (RHK) / Perjanjian Kinerja pimpinan unit di atasnya (intervensi langsung atau tidak langsung atas IKU pimpinan)', 'C. Daftar pekerjaan kantor swasta terdekat', 'D. Nota pembelian alat tulis kantor tahun sebelumnya', 'E. Jadwal libur nasional sepanjang kalender'], 1, 'Prinsip Penyelarasan Vertikal SKP: RHK Bawahan = Mengintervensi RHK Pimpinan (bukan menumpuk aktivitas tak relevan)!', 'MPH memotong duplikasi pekerjaan antarpegawai sehingga seluruh kontribusi anggota tim terukur mendukung target Perjanjian Kinerja unit.'],
    ['Disiplin, Etika, Netralitas & Sistem Informasi ASN (SIASN)', 'sdma-exp-benturan-kepentingan-44', 'Ketika seorang panitia seleksi mutasi/promosi internal mengetahui bahwa keponakan kandungnya menjadi salah satu peserta uji wawancara di ruang yang dipimpinnya, perilaku etika ASN yang wajib dilakukan sebelum seleksi dimulai adalah...', ['A. Tetap menjadi penilai lalu memberikan nilai maksimal supaya keluarga cepat naik pangkat', 'B. Mendeklarasikan adanya benturan kepentingan (conflict of interest) secara tertulis kepada ketua panitia/atasan dan mengundurkan diri (recuse) dari penilaian peserta terkait', 'C. Memberi bocoran soal wawancara malam sebelumnya secara tertutup', 'D. Menurunkan skor peserta lain secara sengaja agar adil', 'E. Melanjutkan penilaian diam-diam dengan alasan bisa bersikap objektif'], 1, 'Conflict of Interest -> Wajib DISCLOSE + RECUSE (tarik diri dari proses penentuan keputusan)!', 'Aturan benturan kepentingan melindungi objektivitas hasil seleksi dan menjaga kredibilitas instansi di hadapan hukum administrasi.'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-record-center-standar-45', 'Pemindahan arsip inaktif ke Records Center (Pusat Arsip Unit Kearsipan) harus memenuhi kaidah teknis penyimpanan arsip fisik yang tepat berupa...', ['A. Diikat karet gelang di lantai terbuka dekat jendela basah', 'B. Dimasukkan ke folder bebas asam, ditata ke dalam boks arsip berlabel kode klasifikasi & daftar arsip inaktif pada rak statis dengan kontrol suhu, kelembapan (RH ~45–55%), dan proteksi hama/api', 'C. Dicampur ke dalam karung plastik bersama perlengkapan kebersihan', 'D. Dilaminating panas seluruh dokumen asli berusia tua termasuk SK dan sertifikat bersejarah', 'E. Diletakkan di ruang terbuka parkir agar terkena angin'], 1, 'Standar Arsip Inaktif: Folder + Boks Arsip + Daftar Arsip + Rak Logam + Kontrol Suhu/Kelembapan (JANGAN laminating dokumen asli bernilai sejarah karena merusak serat)!', 'Laminating plastik permanen dilarang pada konservasi kearsipan modern karena melepaskan gas asam dan merusak keutuhan bahan kertas asli.'],
    ['Kehumasan Pemerintah, Protokol & Keterbukaan Informasi', 'sdma-exp-siaran-pers-piramida-46', 'Dalam menyusun Rilis Berita / Siaran Pers (Press Release) resmi kementerian maupun pemda agar mudah dikutip media massa tanpa mengubah inti kebijakan, struktur penulisan standar jurnalistik yang diterapkan adalah...', ['A. Piramida Terbalik: informasi paling penting (5W+1H / Lead) di paragraf pembuka, diikuti data pendukung/kutipan pejabat, lalu latar belakang tambahan di akhir', 'B. Cerita pembuka bertele-tele 4 halaman sebelum menyebut inti acara di penutup', 'C. Kalimat pujian berlebihan terhadap pribadi pimpinan tanpa data capaian', 'D. Bahasa hukum Latin seluruh paragraf tanpa penjelasan awam', 'E. Hanya mencantumkan dua buah foto tanpa keterangan peristiwa'], 0, 'Press Release = Piramida Terbalik (Lead kuat di paragraf 1 + Kutipan bernilai berita + Fakta terverifikasi + Kontak Humas)!', 'Media redaksi sering memotong naskah dari bawah ke atas, sehingga poin kebijakan terpenting wajib berada di bagian teratas.'],
    ['Studi Kasus SDM Aparatur, Konflik Kerja & Kearsipan', 'sdma-exp-kasus-rekrutmen-fiktif-47', 'Saat mengelola kanal aduan SDM daerah, ditemukan dua warga mengeluhkan penipuan surat "SK Pengangkatan CPNS Jalur Khusus Tanpa Tes" berkop kementerian/Pemda lengkap dengan tanda tangan scan palsu dan permintaan transfer uang. Respons cepat Humas & BKPSDM adalah...', ['A. Mengabaikannya karena penipu berada di luar gedung kantor', 'B. Menerbitkan peringatan resmi Anti-Hoaks di seluruh kanal terverifikasi menegaskan seleksi CASN 100% gratis lewat portal resmi SSCASN BKN, menyimpan barang bukti surat palsu, dan berkoordinasi melapor ke kepolisian/siber', 'C. Meminta korban merahasiakan kasus agar tidak mencemarkan nama kantor', 'D. Memperpanjang validitas surat palsu tersebut atas dasar kasihan', 'E. Menutup sementara pengumuman CASN resmi selama sebulan'], 1, 'Tanggap hoaks CASN: klarifikasi cepat nol-biaya portal SSCASN BKN + kumpulkan bukti dokumen palsu + lapor aparat!', 'Edukasi proaktif mencegah bertambahnya korban penipuan bermodus mutasi/pengangkatan ASN jalur belakang.'],
    ['UU ASN 20/2023 & Sistem Merit Kepegawaian', 'sdma-exp-pemberhentian-tipikor-48', 'Jika seorang PNS terbukti secara sah dan meyakinkan melalui putusan pengadilan berkekuatan hukum tetap (inkracht) melakukan tindak pidana korupsi atau tindak pidana jabatan, maka menurut UU ASN 20/2023 status kepegawaiannya...', ['A. Tetap dipertahankan sampai usia 58 tahun sambil menjalani tahanan', 'B. Diberhentikan tidak dengan hormat sebagai PNS (PTDH) tanpa hak pensiun atas pelanggaran berat jabatan/tipikor', 'C. Cukup dipotong tunjangan makan 10% selama 3 bulan', 'D. Dimutasi ke jabatan fungsional lain tanpa catatan hukum', 'E. Diberi cuti besar berbayar selama masa hukuman'], 1, 'Putusan INKRACHT Tipikor / Tindak Pidana Jabatan -> PTDH (Pemberhentian Tidak Dengan Hormat) mutlak menurut UU ASN!', 'Ketentuan ini berlaku ketat tanpa toleransi guna menjaga marwah pelayanan negara bersih dari korupsi.'],
    ['Anjab, ABK, Evaluasi Jabatan & Manajemen Kinerja SKP', 'sdma-exp-kesenjangan-kompetensi-skj-49', 'Apabila hasil Assessment Center menunjukkan seorang calon pejabat administrator memiliki skor Integritas tinggi (Level 4) namun skor Mengelola Perubahan dan Pengambilan Keputusan masih rendah di bawah Standar Kompetensi Jabatan (Level 2 dari syarat 3), tindak lanjut manajemen SDM adalah...', ['A. Mencoret nama pegawai selamanya dari data kepegawaian', 'B. Menyusun Rencana Pengembangan Individu (IDP — Individual Development Plan) melalui penugasan proyek perubahan, pelatihan kepemimpinan (PKA), serta mentoring terfokus sebelum penempatan penuh', 'C. Mengubah paksa angka rapor hasil asesmen di komputer pengolah angka', 'D. Mempromosikan langsung ke jabatan lebih tinggi lagi tanpa pembinaan', 'E. Memberikan hukuman disiplin pemotongan tunjangan kinerja'], 1, 'Hasil Uji Kompetensi / Assessment Center bukan hanya seleksi lulus/gagal, melainkan peta gap untuk IDP (Individual Development Plan)!', 'IDP terarah memastikan kelemahan spesifik manajerial atau teknis pegawai diisi tepat sasaran lewat pelatihan dan penugasan nyata.'],
    ['Kearsipan Pemerintah (UU 43/2009 & ANRI — Arsiparis)', 'sdma-exp-serah-arsip-akhir-jabatan-50', 'Berdasarkan ketentuan kearsipan nasional (UU 43/2009 & PerANRI), apabila masa jabatan seorang Kepala Daerah, Menteri, atau terjadi pembubaran/penggabungan unit instansi berakhir, seluruh arsip memori jabatan dan arsip dinamisnya wajib...', ['A. Dibawa pulang sebagai koleksi pribadi di rumah mantan pejabat', 'B. Dituangkan dalam Berita Acara Serah Terima (BAST) arsip dan/atau Memori Alih Tugas kepada pejabat pengganti atau diserahkan ke lembaga kearsipan (ANRI/LKD) sesuai statusnya', 'C. Diformat bersih agar pejabat baru memulai dari kertas kosong', 'D. Disimpan di bagasi kendaraan dinas lama tanpa daftar', 'E. Dibuang bersama barang rongsokan gudang'], 1, 'Transisi kepemimpinan/restrukturisasi OPD wajib BAST Arsip + Memori Alih Tugas agar kesinambungan memori kolektif birokrasi terjaga!', 'Hilangnya arsip strategis saat pergantian pimpinan sering memicu sengketa aset tanah/kontrak daerah di masa depan.']
  ];

  /* ==================== 3. SKB AUDITOR & PBJ (+50 Soal -> Total 105 Soal) ==================== */
  const AUDITOR_EXP = [
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-jaminan-75-hps-01', 'Merujuk ketentuan pada bagan Perpres PBJ 16/2018 di bawah, sebuah proyek memiliki HPS Rp1.000 juta dan dimenangkan penyedia dengan penawaran terkoreksi Rp750 juta (75% dari HPS). Berapakah nilai nominal Jaminan Pelaksanaan yang wajib diserahkan penyedia sebelum menandatangani kontrak?', [
      'A. Rp37.500.000 (5% × nilai kontrak Rp750 juta)',
      'B. Rp50.000.000 (5% × nilai total HPS Rp1.000 juta)',
      'C. Rp75.000.000 (10% × nilai kontrak)',
      'D. Rp100.000.000 (10% × total HPS)',
      'E. Tidak wajib menyerahkan jaminan karena di bawah Rp1 miliar'
    ], 1, 'Hafal mati jebakan PBJ klasik: Penawaran < 80% HPS -> Jaminan Pelaksanaan = 5% × TOTAL HPS (bukan 5% nilai kontrak)! 5% × 1.000jt = 50jt!', 'Kewajiban 5% dari total HPS untuk penawaran di bawah 80% HPS bertujuan memitigasi risiko wanprestasi akibat penawaran harga banting.', SVG_PROBITY_HPS],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-hps-sifat-02', 'Harga Perkiraan Sendiri (HPS) dalam pengadaan pemerintah menurut Perpres 16/2018 bersifat terbuka dalam total pagunya namun rincian perhitungannya bersifat rahasia, dengan kegunaan utama sebagai...', ['A. Pembanding tunggal tanpa boleh dinegosiasi pada e-Purchasing', 'B. Alat menilai kewajaran harga penawaran beserta rinciannya, menetapkan batas tertinggi penawaran sah (kecuali lelang terintegrasi), dan dasar penentuan Jaminan', 'C. Harga patokan wajib yang harus dibayar penuh meskipun harga pasar jauh lebih murah', 'D. Dokumen yang disusun setelah kontrak ditandatangani penyedia', 'E. Pengganti bukti kuitansi pajak pertambahan nilai'], 1, 'HPS wajib disusun maks 28 hari kerja sebelum batas pemasukan penawaran, menilai kewajaran harga, dan BUKAN untuk menuntut bayar penuh jika bisa ditawar lebih rendah!', 'Auditor kerap memeriksa dasar survei pasar HPS guna mendeteksi mark-up sistematis sejak fase persiapan pengadaan.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-metode-pl-plang-03', 'Batas nilai maksimal pengadaan Barang, Pekerjaan Konstruksi, dan Jasa Lainnya melalui metode Pengadaan Langsung serta Jasa Konsultansi melalui Pengadaan Langsung menurut Perpres 16/2018 jo 12/2021 adalah...', ['A. Barang/Konstruksi/JL maksimal Rp200 juta; Jasa Konsultansi maksimal Rp100 juta', 'B. Semuanya seragam maksimal Rp500 juta', 'C. Barang maksimal Rp50 juta; Jasa Konsultansi maksimal Rp1 miliar', 'D. Konstruksi maksimal Rp2,5 miliar lewat Pengadaan Langsung', 'E. Tidak ada batas nilai Pengadaan Langsung selama disetujui bendahara'], 0, 'Angka emas PBJ: Pengadaan Langsung Barang/Konstruksi/JL <= Rp200jt; Jasa Konsultansi <= Rp100jt! Penunjukan Langsung hanya untuk kondisi khusus Ps 38(5)!', 'Memecah paket Rp600 juta menjadi tiga paket Rp200 juta agar lolos tender dan menjadi Pengadaan Langsung adalah temuan pelanggaran klasik (splitting paket).'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-konsolidasi-split-04', 'Dalam pemeriksaan Probity Audit pengadaan alat tulis/komputer di sebuah OPD, auditor mendapati 4 paket identik masing-masing Rp190 juta dengan tanggal dan kode rekening sama yang seluruhnya diserahkan kepada toko milik satu keluarga tanpa tender. Praktik ini melanggar larangan...', ['A. E-Purchasing melalui Katalog Elektronik', 'B. Pemecahan paket (splitting) untuk menghindari metode pemilihan Tender/E-Purchasing serta indikasi benturan kepentingan', 'C. Penerapan Tingkat Komponen Dalam Negeri (TKDN)', 'D. Swakelola Tipe III bersama organisasi kemasyarakatan', 'E. Pemberian uang muka kerja'], 1, 'Pemecahan paket menghindari tender (Ps 20 Perpres 16/2018) + afiliasi keluarga (Ps 7 Etika PBJ) = Red Flag kuat Probity Audit!', 'Auditor menyarankan konsolidasi pengadaan serupa atau pemanfaatan Katalog Elektronik yang transparan dan ekonomis.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-swakelola-4tipe-05', 'Pembagian empat tipe Swakelola menurut Perpres 16/2018 yang benar adalah: Tipe I (dikelola sendiri instansi penanggung jawab), Tipe II (instansi lain), Tipe III (Organisasi Kemasyarakatan/Ormas), dan Tipe IV dilaksanakan oleh...', ['A. Vendor perusahaan multinasional komersial', 'B. Kelompok Masyarakat (Pokmas)', 'C. Partai Politik Peserta Pemilu', 'D. Perusahaan Perseorangan Jasa Konstruksi', 'E. Lembaga Konsultan Asing'], 1, 'Hafal 4 Tipe Swakelola: I (Sendiri), II (Instansi Lain), III (Ormas berbadan hukum/Perguruan Tinggi), IV (Kelompok Masyarakat/Pokmas setempat)!', 'Pada Swakelola Tipe IV, PPK menjalin kontrak dengan pimpinan Pokmas untuk kegiatan berbasis partisipasi warga setempat seperti pemeliharaan irigasi tersier desa.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-bast-denda-06', 'Hingga batas akhir masa pelaksanaan kontrak pengadaan 31 Desember, progres fisik pekerjaan baru mencapai 85%, namun PPK menandatangani BAST 100% dan membayarkan seluruh sisa tagihan agar anggaran tidak hangus (LUNAS FIKTIF) sambil berjanji penyedia menyelesaikan sisanya di Januari. Dalam audit APIP, perbuatan tersebut berisiko menimbulkan...', ['A. Penghematan kas negara terbaik tahun anggaran berjalan', 'B. Temuan Kerugian Negara / Kelebihan Pembayaran atas 15% volume belum terpasang, kesalahan pencatatan BAST fiktif, dan pelanggaran Pasal 18 UU Keuangan Negara', 'C. Penghargaan ketepatan serapan APBN tanpa catatan apa pun', 'D. Perubahan otomatis menjadi hibah pemerintah ke penyedia', 'E. Penghapusan kewajiban denda keterlambatan selamanya'], 1, 'Dilarang mutlak BAST 100% fiktif jika fisik belum 100%! Gunakan skema Pembayaran sesuai prestasi riil ATAU Pemberian Kesempatan resmi (PMK/PerLKPP) dengan perpanjangan jaminan & denda 1‰ per hari!', 'Skema pemberian kesempatan melewati tahun anggaran (maks 50 hari kalender) memiliki tata kelola resmi disertai perpanjangan jaminan pelaksanaan dan pengenaan denda 1/1000 per hari.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-tkdn-preferensi-07', 'Dalam pengadaan dengan nilai HPS paling sedikit di atas Rp1 miliar dan terdapat penawaran barang dengan TKDN >= 25%, panitia pemilihan menerapkan "Preferensi Harga" untuk barang/jasa dalam negeri maksimal sebesar...', ['A. 25% untuk Barang/Jasa dan 7,5% untuk Pekerjaan Konstruksi', 'B. 50% untuk seluruh pengadaan konsultan asing', 'C. 5% khusus bagi perusahaan tanpa NPWP', 'D. 100% potongan harga otomatis pada kas daerah', 'E. Tidak ada preferensi harga sama sekali dalam Perpres 12/2021'], 0, 'Preferensi Harga P3DN (Perpres 12/2021): maks 25% (Barang) & maks 7,5% (Pekerjaan Konstruksi yang dikerjakan perusahaan nasional) jika penawaran TKDN >= 25%!', 'Hitung Harga Evaluasi Akhir (HEA) = (1 − KP) × Harga Penawaran, di mana KP = TKDN × Preferensi Tertinggi. Nilai kontrak tetap berdasar harga penawaran asli!'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-pengecualian-spek-08', 'Menurut Pasal 19 ayat (2) Perpres 16/2018, penyebutan merek di dalam Spesifikasi Teknis/KAK pada dasarnya dilarang, KECUALI untuk pengadaan empat kondisi terbatas yakni komponen barang/jasa, suku cadang, bagian sistem sudah ada, atau...', ['A. Barang/jasa pada Katalog Elektronik / Toko Daring', 'B. Barang impor mewah pilihan pribadi pejabat pengadaan', 'C. Merek milik kerabat dekat PPK agar seragam warna gedung', 'D. Seluruh pengadaan pekerjaan jalan beton antarprovinsi', 'E. Jasa konsultan perencana tata ruang kota'], 0, '4 Pengecualian Sebut Merek Ps 19(2): Komponen, Suku Cadang, Bagian Sistem Eksisting, Barang/Jasa pada E-Katalog/Toko Daring!', 'Di luar 4 pengecualian sah tersebut, menyebut merek tunggal pada dokumen tender merupakan pelanggaran prinsip persaingan sehat dalam PBJ.'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-spip-5unsur-09', 'Menurut PP No. 60 Tahun 2008 tentang Sistem Pengendalian Intern Pemerintah (SPIP), lima unsur SPIP yang saling terintegrasi untuk menjamin efektivitas kegiatan, keandalan pelaporan, pengamanan aset, dan ketaatan hukum adalah...', ['A. Lingkungan Pengendalian, Penilaian Risiko, Kegiatan Pengendalian, Informasi & Komunikasi, dan Pemantauan Pengendalian Intern', 'B. Perencanaan, Penganggaran, Lelang, Pencairan, dan Penghentian', 'C. Kepemimpinan, Promosi, Iklan, Diskon, dan Laba', 'D. Pengawasan, Sanksi Pidana, Denda, Penjara, dan Sita Aset', 'E. Surat Tugas, Karcis Parkir, Nota Kas, Stempel, dan Amplop'], 0, '5 Unsur SPIP (adopsi COSO): Lingkungan Pengendalian (fondasi budaya/etika!) + Penilaian Risiko + Kegiatan Pengendalian + Info & Komunikasi + Pemantauan!', 'Lingkungan Pengendalian ("Tone at the Top") menjadi fondasi utama: bila pimpinan sendiri abai pada aturan etika, empat unsur SPIP lainnya sulit berjalan efektif.'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-iacm-level-10', 'Model Kapabilitas Aparat Pengawasan Intern Pemerintah (IACM — Internal Audit Capability Model) mengukur kematangan inspektorat pemerintah dalam 5 tingkatan dari Level 1 (Initial) hingga Level 5 (Optimizing). Inspektorat berstatus Level 3 (Integrated) ditandai dengan kemampuan...', ['A. Pengawasan sepenuhnya masih bergantung pada instruksi acak individu tanpa pedoman baku (ad-hoc)', 'B. Manajemen pengawasan dan praktik profesional sudah terintegrasi penuh ke dalam organisasi, mampu memberi keyakinan memadai terhadap tata kelola dan manajemen risiko unit', 'C. Sama sekali belum memiliki auditor bersertifikat fungsional', 'D. Tidak pernah melakukan audit kinerja maupun reviu LKPD/LKKL', 'E. Hanya menunggu laporan kasus dari media sosial tanpa rencana PKPT'], 1, '5 Level IACM APIP: 1 Initial -> 2 Infrastructure -> 3 Integrated (standar target layanan governance/risk!) -> 4 Managed -> 5 Optimizing!', 'Target strategis pengawasan APIP nasional mendorong Inspektorat Kementerian/Pemda mencapai minimal IACM Level 3 menuju Level 4 (Trusted Advisor).'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-threelines-defense-11', 'Dalam konsep Three Lines Model (Tiga Lini Pertahanan Tata Kelola Risiko Organisasi Pemerintah), posisi dan peran utama Inspektorat (APIP) terletak pada...', ['A. Lini Pertama (pelaksana operasional harian transaksi belanja)', 'B. Lini Kedua (fungsi kepatuhan & manajemen risiko operasional dalam unit kerja)', 'C. Lini Ketiga (pemberi assurance independen dan konsultansi objektif atas efektivitas Lini 1 & Lini 2 langsung kepada pimpinan tertinggi instansi)', 'D. Lembaga yudikatif penjatuh vonis hukuman pidana', 'E. Rekanan penyedia jasa konstruksi swasta'], 2, 'Lini 1 = Unit Operasional/PPK (pemilik risiko); Lini 2 = Unit Kepatuhan/Manajemen Risiko; Lini 3 = APIP/Inspektorat (Independent Assurance)!', 'APIP dilarang mengambil alih kewenangan Lini 1 seperti menandatangani kuitansi persetujuan belanja atau memutus pemenang lelang agar independensinya terjaga!'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-kode-etik-aai-12', 'Empat prinsip utama Kode Etik Auditor Intern Pemerintah Indonesia (AAIPI) yang wajib dipegang penuh dalam setiap penugasan pengawasan adalah...', ['A. Integritas, Objektivitas, Kerahasiaan, dan Kompetensi', 'B. Kecepatan, Kekerasan, Popularitas, dan Keseragaman', 'C. Keuntungan, Kompromi, Keberpihakan, dan Keramaian', 'D. Kepatuhan Pribadi pada Auditi, Kebebasan Beropini Tanpa Bukti, Kesepakatan Lisan, dan Rahasia Keluarga', 'E. Kreativitas Mengubah Angka, Kepentingan Unit, Kedekatan Sosial, dan Senioritas'], 0, '4 Prinsip Kode Etik AAIPI: Integritas · Objektivitas · Kerahasiaan · Kompetensi! ("IKOK")', 'Jika terjadi gangguan independensi (misal pernah menjabat sebagai PPK objek yang diaudit dalam 1 tahun terakhir), auditor wajib menolak penugasan itu (cooling-off).'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-sae-assurance-vs-consult-13', 'Perbedaan mendasar antara penugasan Assurance (Audit/Reviu/Evaluasi/Pemantauan) dengan penugasan Konsultansi oleh Inspektorat dalam Standar Audit AAIPI adalah...', ['A. Pada penugasan Assurance ada 3 pihak (APIP, auditi, pengguna laporan), sifat penilaian independen atas bukti; sedangkan Konsultansi sifatnya pendampingan/saran perbaikan atas permintaan manajemen tanpa mengambil alih tanggung jawab eksekutif', 'B. Pada penugasan Konsultansi auditor wajib ikut menandatangani SPM pencairan uang', 'C. Penugasan Assurance tidak memerlukan Kertas Kerja Audit sama sekali', 'D. Konsultansi bermakna memberikan bantuan dana kas kepada dinas', 'E. Keduanya dilarang dilakukan oleh auditor bersertifikat'], 0, 'Assurance = 3 pihak & beri simpulan/opini objektif (Audit, Reviu, Evaluasi, Pemantauan); Konsultansi = 2 pihak & beri nasihat/pendampingan manajemen risiko!', 'Contoh nyata konsultansi: pendampingan penyusunan Daftar Risiko (Risk Register) SPIP atau bimbingan teknis penyusunan laporan keuangan sebelum direviu.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-vouching-vs-tracing-14', 'Dua teknik pengujian bukti dokumen dalam audit keuangan yang saling berlawanan arah: "Vouching" dan "Tracing". Bila auditor menelusuri angka di Laporan Keuangan (Buku Besar) mundur kembali ke faktur/SPJ asli guna menguji apakah transaksi benar terjadi (existence/occurrence), teknik ini disebut...', ['A. Tracing (menguji kelengkapan/completeness dari bukti ke buku besar)', 'B. Vouching (menguji keterjadian/keabsahan/existence dari catatan pembukuan mundur ke bukti dokumen asal)', 'C. Konfirmasi Lisan Tanpa Dokumen', 'D. Stock Opname Persediaan Obat', 'E. Inspeksi Fisik Gedung di Lapangan'], 1, 'Ingat mudah: V-O-uching = menguji Occurrence (dari Jurnal/Laporan MUNDUR ke Bukti fisik); Tra-C-ing = menguji Completeness (dari Bukti asli MAJU ke Jurnal)!', 'Vouching sangat ampuh mendeteksi belanja fiktif atau pengeluaran tanpa dukungan bukti autentik yang sah.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-audit-kinerja-3e-15', 'Berbeda dari audit keuangan/ketaatan yang berfokus pada kesesuaian SAP dan aturan, Audit Kinerja APIP menilai apakah suatu program instansi telah memenuhi prinsip "3E", yaitu...', ['A. Ekonomi (perolehan input termurah kualitas memadai), Efisiensi (rasio output vs input), dan Efektivitas (ketercapaian outcome/tujuan sasaran)', 'B. Ekspansi, Eksploitasi, dan Ekspektasi', 'C. Ejaan, Estetika, dan Etiket Kantor', 'D. Elektronik, Emisi, dan Energi Listrik', 'E. Evaluasi, Eksekusi, dan Eksaminasi'], 0, '3E Audit Kinerja: Ekonomi (Input murah berkualitas) · Efisiensi (Output/Input optimal) · Efektivitas (Outcome tepat sasaran)!', 'Program bisa sangat Ekonomis dan Efisien dalam mencetak 10.000 brosur murah, namun TIDAK Efektif bila angka partisipasi warga tetap nol!'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-kka-5c-atribut-16', 'Dalam penyusunan temuan audit pada Kertas Kerja Audit (KKA) maupun Laporan Hasil Audit (LHA), kelengkapan 5 unsur temuan ("5C" — Conditions, Criteria, Cause, Consequence/Effect, Corrective Action) wajib dibangun berurutan. Unsur "Kriteria" (Criteria) merujuk pada...', ['A. Fakta penyimpangan yang benar-benar ditemukan auditor di lapangan (Kondisi)', 'B. Peraturan perundang-undangan, SOP resmi, kontrak, atau standar yang seharusnya dipatuhi sebagai tolok ukur (What Should Be)', 'C. Faktor akar penyebab kelemahan SPIP mengapa penyimpangan terjadi (Sebab)', 'D. Besaran kerugian negara atau dampak terhambatnya layanan publik (Akibat)', 'E. Saran perbaikan sistem dan tuntutan pengembalian ke kas negara (Rekomendasi)'], 1, 'Conditions = What Is; Criteria = What Should Be; Cause = Why it happened; Effect = So what; Recommendation = Fix cause & impact!', 'Kesalahan umum auditor pemula adalah rekomendasi hanya meminta pengembalian uang tanpa memperbaiki akar Sebab (Cause) kelemahan kontrol internalnya.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-reviu-rka-vs-audit-17', 'Berbeda dengan audit mendalam setelah kejadian, "Reviu RKA-KL / RKA-SKPD" dan "Reviu Laporan Keuangan" oleh Inspektorat dilaksanakan dengan tingkat keyakinan...', ['A. Keyakinan mutlak (100% seluruh kuitansi diperiksa detail satu per satu)', 'B. Keyakinan terbatas (limited assurance) terutama berbasis prosedur analitis dan wawancara guna memberi keyakinan bahwa RKA/LK telah disusun sesuai standar sebelum ditetapkan/diaudit BPK', 'C. Tanpa keyakinan apa pun dan tanpa kertas kerja', 'D. Memberikan opini Wajar Tanpa Pengecualian (WTP) menggantikan BPK', 'E. Menggantikan fungsi DPRD menyetujui tarif pajak'], 1, 'Audit = Reasonable Assurance; Reviu = Limited Assurance (prosedur analitis & penelusuran kesalahan penyajian sebelum disahkan/diaudit BPK)!', 'Hanya BPK RI selaku pemeriksa eksternal yang berwenang memberikan Opini resmi WTP/WDP/TMP/TW atas Laporan Keuangan Pemerintah.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-fraud-triangle-cressy-18', 'Menurut teori klasik Fraud Triangle (Donald Cressey) yang wajib dikenali Auditor Investigatif saat mendeteksi kecurangan pengadaan maupun perjalanan dinas fiktif, 3 elemen pendorong kecurangan adalah...', ['A. Tekanan/Dorongan (Pressure), Kesempatan/Celah Kontrol Lemah (Opportunity), dan Pembenaran Diri (Rationalization)', 'B. Pendidikan Tinggi, Umur Senior, dan Gaji Besar', 'C. Peraturan Jelas, Audit Rutin, dan Sistem Digital', 'D. Cuaca Buruk, Jarak Dekat, dan Hari Libur', 'E. Loyalitas, Integritas, dan Akuntabilitas'], 0, 'Fraud Triangle = Pressure + Opportunity (celah SPIP lemah -> paling bisa ditutup APIP!) + Rationalization ("cuma sedikit/semua juga begini").', 'Dalam audit pencegahan, memperkuat SPIP langsung memotong kaki terpenting dari Fraud Triangle yaitu Opportunity!'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-tlhp-60hari-19', 'Batas waktu wajib bagi pimpinan instansi/Pemda menindaklanjuti Rekomendasi Hasil Pemeriksaan BPK dan/atau APIP sejak laporan diterima secara sah menurut UU No. 15 Tahun 2004 adalah...', ['A. Paling lambat 7 hari kalender', 'B. Paling lambat 60 hari setelah laporan hasil pemeriksaan diterima', 'C. 365 hari kerja di akhir tahun berikutnya', 'D. 5 tahun menjelang pergantian kepala daerah', 'E. Tidak ada batas waktu wajib jika bendahara sudah mutasi'], 1, 'Pasal 20 UU 15/2004: Wajib menindaklanjuti rekomendasi LHP paling lambat 60 hari sejak diterima!', 'Pemantauan Tindak Lanjut Hasil Pengawasan (TLHP) menentukan kredibilitas pengawasan sekaligus memengaruhi nilai Opini BPK atas LKPP/LKPD.'],
    ['Pengawasan Urusan Pemda (PPUPD) & Keuangan Desa', 'aud-exp-ppupd-vs-auditor-20', 'Perbedaan fokus utama peran Pejabat Pengawas Penyelenggaraan Urusan Pemerintahan Daerah (PPUPD — Kemendagri) dibanding Auditor APIP dalam Inspektorat Daerah adalah...', ['A. PPUPD lebih berfokus pada pengawasan penyelenggaraan urusan pemerintahan daerah (ketaatan NSPK pusat-daerah, SPM, Perda/Perkada, pelayanan publik daerah), sedangkan Auditor lebih berfokus pada pengawasan keuangan, kinerja program, audit investigatif, dan reviu akuntabilitas fiskal', 'B. PPUPD hanya bertugas di kementerian pusat luar negeri tanpa pernah ke Pemda', 'C. Auditor dilarang memeriksa laporan keuangan Pemda', 'D. PPUPD merupakan jabatan struktural kepala dinas pekerjaan umum', 'E. Keduanya tidak termasuk unsur APIP Inspektorat Daerah'], 0, 'Sinergi Inspektorat Daerah = PPUPD (NSPK, urusan wajib/pilihan Pemda, SPM, kinerja kepala daerah) + Auditor (Keuangan, Aset, PBJ, Probity, Investigasi)!', 'Dalam praktiknya di Inspektorat Pemda, tim pengawasan reguler sering menggabungkan Auditor dan PPUPD secara kolaboratif.'],
    ['Pengawasan Urusan Pemda (PPUPD) & Keuangan Desa', 'aud-exp-siswaskeudes-redflag-21', 'Pemanfaatan aplikasi Siswaskeudes (Sistem Pengawasan Keuangan Desa) oleh APIP Daerah bertujuan mengefektifkan pengawasan terhadap ribuan desa melalui mekanisme...', ['A. Pemeriksaan manual 100% seluruh nota belanja tiap desa setiap minggu ke lapangan', 'B. Audit berbasis risiko (risk-based audit) dengan analisis data Siskeudes secara jarak jauh mendeteksi red flags belanja/kas tak wajar sebelum menentukan desa sampel uji petik lapangan', 'C. Menghapus kewenangan kepala desa menandatangani APBDes', 'D. Mengalihkan seluruh Dana Desa menjadi belanja gaji pegawai kabupaten', 'E. Menutup akses pelaporan Badan Permusyawaratan Desa (BPD)'], 1, 'Siswaskeudes = Computer-Assisted Audit Technique (CAATs) + Risk-Based Audit menyaring ribuan desa secara cerdas!', 'Dengan CAATs/Siswaskeudes, auditor bisa langsung melihat lonjakan SILPA tak wajar, keterlambatan setor pajak bendahara desa, atau penarikan tunai besar sebelum turun cek fisik.'],
    ['Studi Kasus Audit, PBJ & Pengawasan APIP', 'aud-exp-kasus-perjadin-fiktif-22', 'Saat audit ketaatan di suatu dinas, auditor menemukan 15 kuitansi perjalanan dinas mencantumkan bukti menginap di hotel yang sama namun tanggalnya bertumpang tindih dengan daftar hadir rapat di kantor asal serta kode booking hotel tak tercatat di resepsionis hotel saat konfirmasi. Tindakan audit paling tepat adalah...', ['A. Membiarkan saja karena nilainya di bawah Rp100 juta per kuitansi', 'B. Mendokumentasikan bukti uji silang absensi dan berita acara konfirmasi hotel di KKA sebagai indikasi pertanggungjawaban fiktif, menghitung total kelebihan bayar, merekomendasikan penyetoran kembali ke Kas Negara/Daerah (TGR/SKP2K), dan pemberian sanksi sesuai PP Disiplin', 'C. Meminta bendahara mencetak kuitansi pengganti bertanggal berbeda', 'D. Menghapus berita acara konfirmasi hotel agar suasana auditi nyaman', 'E. Mengumumkan nama pelanggar secara sepihak di media sosial pribadi auditor'], 1, 'Audit Investigatif/Ketaatan: Uji Silang Dokumen + Konfirmasi Pihak Ketiga -> Dokumentasi KKA -> Setor Kas Negara/Daerah + Sanksi Disiplin!', 'Menjaga kerahasiaan proses pengawasan hingga LHA resmi terbit adalah bagian dari Kode Etik AAIPI.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-adendum-10pct-23', 'Dalam pekerjaan konstruksi maupun pengadaan barang akibat penyesuaian kebutuhan lapangan di tengah kontrak (Contract Change Order / Addendum kontrak tambah kurang), batas maksimal penambahan nilai kontrak menurut Perpres 16/2018 tidak boleh melebihi...', ['A. 5% dari nilai kontrak awal', 'B. 10% dari harga yang tercantum dalam kontrak awal (sepanjang anggaran tersedia)', 'C. 35% tanpa batas persetujuan anggaran', 'D. 50% asalkan penyedia setuju', 'E. 100% dengan metode penunjukan lisan'], 1, 'Angka wajib hafal PBJ: Addendum Penambahan Nilai Kontrak MAX 10% dari kontrak awal (dengan ketersediaan Pagu Anggaran)!', 'Jika penyesuaian lapangan menurunkan satu item untuk menambah item krusial lain tanpa melebihi +10%, PPK wajib melampirkan justifikasi teknis tertulis sebelum tanda tangan adendum.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-uangmuka-24', 'Batas maksimal pemberian Uang Muka pengadaan pada Kontrak Usaha Kecil vs Kontrak Non-Kecil/Pekerjaan Terintegrasi menurut Perpres PBJ 16/2018 jo 12/2021 adalah...', ['A. Usaha Kecil max 30% (atau hingga 50% untuk Usaha Mikro/Kecil dalam aturan perubahan tertentu Perpres 12/2021? Cek: Mikro/Kecil paling tinggi 50% untuk kontrak <= Rp200jt? Tepat: Perpres 12/2021 Ps 29: <=30% untuk usaha kecil secara umum, <=20% non-kecil/konsultansi, atau max 50% untuk usaha kecil nilai pagu tertentu/tahun jamak <=15%?)', 'B. Seluruh penyedia wajib dibayar 100% di muka sebelum barang dikirim', 'C. Usaha Kecil paling tinggi 30% dan Usaha Non-Kecil paling tinggi 20% (serta Kontrak Tahun Jamak max 15%), dengan syarat wajib menyerahkan Jaminan Uang Muka senilai uang muka diterima', 'D. Uang muka maksimal 75% untuk penyedia baru berdiri 1 hari tanpa jaminan', 'E. Uang muka dilarang total di seluruh kementerian Indonesia'], 2, 'Uang Muka PBJ: Usaha Kecil max 30% (atau ketentuan UMK), Non-Kecil/Konsultan max 20%, Tahun Jamak max 15% + WAJIB Jaminan Uang Muka 100% dari nilai uang muka!', 'Cek Jaminan Uang Muka sangat vital dalam audit: jika penyedia wanprestasi di tengah proyek, PPK wajib mencairkan sisa Jaminan Uang Muka tersebut ke kas negara/daerah.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-denda-1permil-25', 'Jika penyedia terlambat menyelesaikan pekerjaan setelah batas akhir kontrak (dan tidak putus kontrak), pengenaan denda keterlambatan resmi menurut kontrak standar Perpres 16/2018 sebesar...', ['A. 1‰ (satu per seribu / 0,1%) per hari keterlambatan dari nilai kontrak ATAU dari bagian kontrak yang belum selesai (sesuai pilihan di kontrak)', 'B. 5% per hari dari seluruh anggaran APBD daerah', 'C. Rp10.000 per minggu tanpa memandang nilai proyek', 'D. 10% per bulan tanpa memperhitungkan hari', 'E. Denda boleh dihapus PPK secara sepihak agar penyedia senang'], 0, 'Denda Keterlambatan PBJ = 1/1000 (1 permil = 0,1%) per hari! Nilai kontrak vs Bagian kontrak (jika bagian tsb berfungsi independen)!', 'Auditor sering menemukan PPK lupa memotong denda keterlambatan dari tagihan akhir atau salah dasar perhitungannya ketika pekerjaan terbagi atas sub-bagian fungsional.'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-audit-sampling-26', 'Ketika memeriksa 4.500 kuitansi bantuan operasional atau belanja rutin berisiko seragam dan auditor memilih sebagian sampel representatif untuk menarik kesimpulan populasi secara objektif, metode terbaik agar risiko salah simpulan dapat terukur secara matematis adalah...', ['A. Memilih 3 map paling tipis yang diletakkan di meja paling atas saja', 'B. Statistical Sampling (seperti Monetary Unit Sampling / Attribute Sampling dengan tingkat kepercayaan & toleransi salah saji terukur)', 'C. Meminta auditi memilihkan sendiri 5 berkas terbagus untuk diperiksa auditor', 'D. Hanya memeriksa berkas milik pegawai yang tidak akrab dengan tim', 'E. Tidak memeriksa satu kuitansi pun lalu langsung menulis hasil aman'], 1, 'Sampling Statistik memberi presisi terukur; hindari bias memilihkan sampel oleh auditi!', 'Untuk item bernilai sangat besar atau berisiko tinggi (key items / high-risk transactions), auditor tetap menguji 100% di luar lapisan sampel acak lainnya.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-konfirmasi-eksternal-27', 'Dalam hierarki keandalan bukti audit (reliability of audit evidence), bukti manakah yang paling tinggi kekuatan pembuktiannya jika terjadi perbedaan catatan?', ['A. Penjelasan lisan pengelola barang di ruang rapat tanpa catatan', 'B. Bukti eksternal langsung dari pihak ketiga independen (seperti rekening koran langsung dari bank atau konfirmasi tertulis penyedia/penerima hibah) ditambah pemeriksaan fisik langsung auditor', 'C. Fotokopi kuitansi tanpa tanda tangan yang dikirim lewat aplikasi pesan', 'D. Catatan memo pribadi staf pengadaan pada kertas buram', 'E. Perkiraan auditor tanpa melihat dokumen'], 1, 'Keandalan bukti terbaik: Pemeriksaan Fisik Langsung Auditor + Bukti Pihak Eksternal Independen langsung ke auditor!', 'Bukti internal organisasi yang melewati pengendalian SPIP kuat jauh lebih andal daripada dokumen internal tanpa tanda otorisasi dan penjelasan lisan sepihak.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-reviu-lk-opini-wajar-28', 'Saat melakukan Reviu Laporan Keuangan Kementerian/Daerah sebelum diserahkan ke BPK, auditor APIP menemukan aset tetap kendaraan dan gedung senilai Rp40 miliar masih bersaldo "dalam sengketa/tidak diketahui keberadaannya" tanpa daftar inventaris rinci maupun penyusutan. Temuan ini berisiko langsung memengaruhi BPK dalam memberikan opini...', ['A. Wajar Tanpa Pengecualian (WTP) murni tanpa catatan', 'B. Wajar Dengan Pengecualian (WDP) atau bahkan Tidak Memberikan Pendapat (Disclaimer) jika nilainya material dan luas memengaruhi penyajian Neraca Aset Tetap', 'C. Penghargaan Pengelola Aset Tercepat', 'D. Penghapusan utang jangka pendek daerah secara otomatis', 'E. Kenaikan kelas jabatan pengurus barang'], 1, 'Aset Tetap tak jelas fisik/nilai + Persediaan tak akurat + Kas bermasalah = Trio penyebab utama LKPD/LKKL gagal meraih WTP!', 'Tujuan utama Reviu LK APIP sebelum Maret adalah mendeteksi dan mendorong koreksi jurnal/inventarisasi aset sebelum BPK melakukan audit rinci.'],
    ['Pengawasan Urusan Pemda (PPUPD) & Keuangan Desa', 'aud-exp-evaluasi-apbdes-pad-29', 'Pengawasan terhadap ketepatan penganggaran Dana Desa dan Alokasi Dana Desa (ADD) oleh PPUPD/APIP wajib memastikan prioritas antara lain...', ['A. Minimal 70% digunakan untuk membeli mobil dinas perangkat desa', 'B. Kesesuaian batas belanja operasional/Penghasilan Tetap (Siltap) pemerintah desa paling tinggi 30% dari total anggaran belanja APBDes serta pemenuhan prioritas BLT/ketahanan pangan/stunting sesuai PMK/Permendesa tahun berjalan', 'C. Seluruh dana dibagikan tanpa APBDes maupun Musyawarah Desa', 'D. Pembangunan dilakukan tanpa RAB teknis maupun papan informasi desa', 'E. Pungutan pajak PPh/PPN oleh bendahara desa disimpankan di tabungan pribadi'], 1, 'Aturan emas PP 11/2019 & Pengawasan Desa: Belanja operasional/Siltap/Tunjangan Desa <= 30% APBDes; >= 70% wajib untuk pembangunan/pembinaan/pemberdayaan!', 'Selain aturan 30:70 APBDes, APIP kerap menemukan keterlambatan setor pajak desa (PPN/PPh 21/22/23) dan kekurangan volume fisik pekerjaan rabat beton.'],
    ['Studi Kasus Audit, PBJ & Pengawasan APIP', 'aud-exp-kasus-pbj-ekatalog-30', 'Pembelian 50 unit laptop lewat Katalog Elektronik (e-Purchasing) dilakukan PPK langsung mengklik merek berharga Rp24 juta per unit padahal tersedia beberapa penyedia produk spesifikasi setara bersertifikat TKDN pada harga Rp14 juta di Katalog tanpa bukti perbandingan negosiasi/harga pasar. Audit APIP mencatat penyimpangan berupa...', ['A. Sah sepenuhnya karena e-Katalog membebaskan PPK dari prinsip value for money dan efisiensi', 'B. Pelanggaran prinsip efisien, ekonomis, dan kewajiban dokumentasi kertas kerja pemilihan/negosiasi harga pada e-Purchasing sehingga menimbulkan indikasi pemahalan harga/kerugian negara', 'C. Kewajiban menambah jumlah pembelian menjadi 100 unit', 'D. Hanya masalah selera warna casing laptop yang tidak seragam', 'E. Tidak boleh diaudit karena sudah lewat aplikasi daring'], 1, 'Mitos salah di kalangan PPK: "Asal beli di e-Katalog otomatis kebal audit!" Salah -> prinsip Value for Money, kompetisi sehat & dokumentasi negosiasi WAJIB ada!', 'Audit Katalog Elektronik memverifikasi alasan pemilihan penyedia, bukti pembandingan spesifikasi/harga pasar, kesesuaian pengiriman, hingga keabsahan biaya ongkir/garansi.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-ppk-pokja-peran-31', 'Agar terhindar dari konflik kewenangan dan menjaga check-and-balance dalam struktur organisasi pengadaan Perpres 16/2018, pihak yang menetapkan Spesifikasi Teknis, HPS, dan Rancangan Kontrak vs pihak yang melaksanakan proses Tender dan menetapkan Penyedia Pemenang (di bawah Rp100 M) berturut-turut adalah...', ['A. Bendahara Pengeluaran dan Kepala Gudang', 'B. Pejabat Pembuat Komitmen (PPK) dan Pokja Pemilihan (UKPBJ)', 'C. Pengguna Anggaran dan Inspektur Jenderal', 'D. Penyedia Barang dan Konsultan Pengawas', 'E. Anggota DPRD dan Satpol PP'], 1, 'Pemisahan Peran PBJ: PA/KPA (tetapkan RUP & kontrak jumbo) -> PPK (Spek/HPS/Kontrak/Bayar) -> Pokja UKPBJ (Proses Tender & Tetapkan Pemenang)!', 'PPK dilarang merangkap menjadi Pokja Pemilihan/Pejabat Pengadaan pada paket yang sama agar tidak terjadi monopoli penentuan pemenang.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-daftar-hitam-32', 'Penyedia yang mengundurkan diri saat masa tender dengan alasan tidak dapat diterima atau terbukti menyampaikan dokumen kualifikasi palsu maupun membatalkan kontrak sepihak akan dikenai sanksi administratif berupa pencairan jaminan beserta pencantuman dalam...', ['A. Daftar Prioritas Mitra Teladan Nasional', 'B. Daftar Hitam (Blacklist) Nasional LKPP selama jangka waktu 1 tahun atau 2 tahun (tergantung jenis pelanggaran)', 'C. Penambahan bonus uang kontrak 10%', 'D. Penghapusan kewajiban bayar pajak badan', 'E. Pengangkatan menjadi Pejabat Pengadaan'], 1, 'Pelanggaran dokumen palsu / wanprestasi kontrak -> Sanksi Daftar Hitam (1 tahun untuk wanprestasi/mundur; 2 tahun untuk pemalsuan/persekongkolan)!', 'Selama masa Daftar Hitam berlaku di portal INAPROC/LKPP, perusahaan tersebut (beserta pengurus terkait sesuai aturan) dilarang mengikuti pengadaan pemerintah seluruh Indonesia.'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-pkpt-riskbased-33', 'Penyusunan Program Kerja Pengawasan Tahunan (PKPT) Inspektorat modern tidak lagi membagi jadwal pemeriksaan secara rata bergiliran (cyclical), melainkan berbasis...', ['A. Permintaan lisan teman dekat', 'B. Audit Berbasis Risiko (Risk-Based Internal Auditing) memprioritaskan unit kerja/program dengan profil risiko inheren tinggi, pagu anggaran strategis, dan kerentanan kecurangan', 'C. Urutan abjad nama dinas dari A hingga Z', 'D. Jarak lokasi kantor paling dekat dari hotel berbintang', 'E. Jumlah pegawai laki-laki di masing-masing dinas'], 1, 'PKPT Risk-Based = fokuskan sumber daya auditor terbatas ke area anggaran jumbo & risiko tinggi (High Risk)!', 'Pendekatan berbasis risiko mengoptimalkan dampak pencegahan kerugian negara dibanding sekadar menyebar auditor tipis-tipis tanpa pendalaman.'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-penilaian-risiko-inheren-34', 'Dalam matriks Manajemen Risiko SPIP, risiko suatu kegiatan sebelum adanya pengendalian apa pun disebut "Risiko Inheren", sedangkan tingkat risiko yang masih tersisa setelah pimpinan menerapkan SOP, pemisahan fungsi, dan aplikasi pengawasan disebut...', ['A. Risiko Fiktif', 'B. Risiko Residual (Residual Risk)', 'C. Risiko Nihil Mutlak', 'D. Risiko Likuidasi Swasta', 'E. Risiko Modal Asing'], 1, 'Inheren (bawaan awal) − Pengendalian Efektif = Risiko Residual! Bila Residual > Risk Appetite pimpinan, tambah rencana mitigasi!', 'Penilaian efektivitas pengendalian (Control Self-Assessment / CSA) menentukan apakah pengendalian di SOP benar-benar berjalan di lapangan atau hanya formalitas kertas.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-probity-5tahap-35', 'Keunggulan utama pelaksanaan "Probity Audit" pada proyek pengadaan strategis berisiko tinggi (seperti pembangunan RSUD atau sistem TI utama) dibandingkan audit ketaatan pasca-kontrak selesai adalah...', ['A. Probity audit dilakukan secara real-time pada tiap tahapan kritis pengadaan (Perencanaan -> Persiapan -> Pemilihan -> Kontrak -> Serah Terima) untuk mencegah cacat prosedur dan kerugian sebelum dana telanjur keluar', 'B. Probity audit dilaksanakan 5 tahun setelah proyek rusak agar nilai denda lebih besar', 'C. Probity audit mengizinkan auditor ikut memilih merek milik temannya', 'D. Probity audit membebaskan penyedia dari kewajiban jaminan pemeliharaan', 'E. Probity audit hanya dilakukan untuk pengadaan konsumsi rapat di bawah Rp5 juta'], 0, 'Probity Audit = "Pencegahan Real-Time" mengawal integritas proses PBJ tahap demi tahap sebelum kerugian terjadi!', 'Namun perlu diingat, pemberian catatan Probity oleh auditor tidak menghilangkan tanggung jawab hukum pribadi PPK maupun Pokja Pemilihan atas keputusan pengadaannya.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-audit-aset-idle-36', 'Selama audit manajemen Barang Milik Negara/Daerah (BMN/BMD), auditor menemukan gedung eks kantor senilai Rp15 miliar dibiarkan kosong terbengkalai selama 4 tahun tanpa pemanfaatan dan tetap menelan biaya penjagaan rutin. Rekomendasi optimal auditor adalah...', ['A. Membiarkannya sampai roboh sendiri untuk menghemat catatan akuntansi', 'B. Merekomendasikan penetapan status penggunaan/alih status pemanfaatan (sewa/pinjam pakai/KSP/hibah sesuai PP 27/2014 jo 28/2020) agar produktif atau memberi PNBP/PAD serta mengamankan sertifikat hak pakai', 'C. Mengizinkan oknum staf menempatinya secara pribadi gratis tanpa izin', 'D. Menghapus aset tersebut dari Neraca tanpa proses penghapusan resmi BMN/BMD', 'E. Menggadaikannya ke bank perkreditan rakyat'], 1, 'Aset Idle = biaya pemeliharaan tinggi & risiko penyerobotan lahan -> dorong Sertifikasi Legal + Optimalisasi Pemanfaatan (Sewa/KSP/Alih Status)!', 'Pengamanan aset meliputi 3 aspek: pengamanan fisik (pagar/plang), pengamanan administrasi (SIMAK/KIB), dan pengamanan hukum (sertifikat atas nama pemerintah).'],
    ['Pengawasan Urusan Pemda (PPUPD) & Keuangan Desa', 'aud-exp-spm-evaluasi-daerah-37', 'Dalam pengawasan penerapan Standar Pelayanan Minimal (SPM) oleh PPUPD di pemerintah kabupaten/kota, objek utama yang dinilai tidak hanya laporan serapan kas dinas melainkan...', ['A. Jumlah piala pajangan di lobi bupati', 'B. Keterpenuhan data sasaran warga berhak, pemenuhan mutu layanan dasar minimal (kesehatan, pendidikan, sosial, PU, perkim, trantibum), serta prioritas alokasi anggarannya dalam APBD', 'C. Jumlah unggahan foto kegiatan kepala dinas di media sosial', 'D. Besaran tunjangan kinerja pejabat pimpinan tinggi saja', 'E. Banyaknya proyek tugu selamat datang di perbatasan'], 1, 'Pengawasan SPM mengecek: Apakah 100% warga sasaran mendapat layanan dasar sesuai standar mutu Permendagri 59/2021!', 'Pemda wajib memprioritaskan pemenuhan SPM layanan dasar di dalam RKPD dan APBD sebelum membiayai program non-dasar lainnya.'],
    ['Studi Kasus Audit, PBJ & Pengawasan APIP', 'aud-exp-kasus-mark-up-ongkir-38', 'Saat memeriksa laporan belanja modal alat laboratorium Rp2 miliar, ditemukan penyedia menagihkan biaya kalibrasi dan asuransi pengiriman terpisah padahal dalam Syarat Khusus Kontrak dan rincian HPS sudah bersifat kontrak lump sum termasuk pelatihan dan kalibrasi. Langkah auditor yang tepat...', ['A. Menyetujui pembayaran ganda karena kalibrasi adalah jasa penting', 'B. Mengeluarkan catatan temuan kelebihan pembayaran (double billing) atas biaya kalibrasi/pengiriman dan merekomendasikan pemotongan tagihan / pengembalian ke kas negara/daerah', 'C. Mengubah jenis kontrak di belakang hari secara lisan menjadi kontrak harga satuan', 'D. Menahan seluruh pembayaran tanpa menjelaskan klausul kontrak', 'E. Meminta penyedia membagi separuh tagihan tersebut ke rekening kantor'], 1, 'Cek selalu ruang lingkup harga di SSKK/Kontrak & HPS agar tidak terjadi pembayaran ganda (Double Billing) atas item yang sudah included!', 'Kontrak Lump Sum mengikat ruang lingkup keluaran menyeluruh kecuali terdapat perubahan spesifikasi resmi dari PPK.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-gagal-tender-39', 'Menurut Perpres 16/2018, manakah kondisi berikut yang menyebabkan Pokja Pemilihan wajib menyatakan Tender/Seleksi GAGAL sebelum penetapan pemenang?', ['A. Terdapat kesalahan dalam Dokumen Pemilihan yang tidak sesuai ketentuan, tidak ada peserta menyampaikan penawaran setelah batas waktu perpanjangan, seluruh penawaran melampaui HPS, atau ditemukan indikasi KKN/persaingan usaha tidak sehat', 'B. Hanya ada 3 peserta yang mengajukan penawaran harga di bawah HPS', 'C. Harga penawaran terendah berbeda Rp1 juta dari perkiraan staf', 'D. Pemenang sementara berdomisili di kabupaten tetangga namun masih di Indonesia', 'E. Penawaran peserta menggunakan produk dalam negeri ber-TKDN tinggi'], 0, 'Syarat Tender Gagal ketat diatur Pasal 51 Perpres PBJ (bukan karena peserta luar kota atau pakai TKDN tinggi)!', 'Jika dua kali tender ulang tetap gagal tanpa pemenang, PP/KPA dapat memproses penunjukan langsung sesuai syarat ketat ketentuan PBJ.'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-wbk-wbs-audit-40', 'Keberadaan Whistleblowing System (WBS — Sistem Pengaduan Pelanggaran) yang menjamin kerahasiaan identitas pelapor sangat membantu fungsi pengawasan APIP dalam hal...', ['A. Membuka kanal awal deteksi dini kecurangan tersembunyi (fraud/suap) yang sering tidak tampak pada pemeriksaan dokumen normal', 'B. Menangkap warga yang mengkritik jalan rusak di media sosial', 'C. Membagikan bonus tunai kepada rekanan pelanggar kontrak', 'D. Menggantikan fungsi sistem akuntansi akrual LKPD', 'E. Mengumumkan seluruh gaji pegawai secara acak'], 0, 'ACFE Report consistently shows: >40% fraud terungkap pertama kali lewat "Tips / Whistleblowing", jauh melampaui audit rutin biasa!', 'Perlindungan identitas pelapor beritikad baik (good faith whistleblower) wajib dijaga agar pegawai berani melapor tanpa takut pembalasan atasan.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-exit-meeting-ba-41', 'Tujuan utama pelaksanaan Exit Meeting (Pembahasan Akhir Hasil Pengawasan) sebelum LHA diterbitkan dan ditandatangani oleh tim auditor APIP bersama pimpinan auditi adalah...', ['A. Mengonfirmasi keakuratan fakta temuan, mendengar tanggapan/klarifikasi tertulis auditi disertai bukti sah terbaru, serta menyepakati rencana tindak perbaikan yang realistis tanpa mengorbankan independensi temuan valid', 'B. Bernegosiasi menghapus temuan kerugian negara demi menjaga hubungan baik', 'C. Meminta fasilitas perjalanan pulang tim auditor dari anggaran unit auditi', 'D. Mengganti seluruh angka temuan sesuai keinginan kepala dinas', 'E. Membubarkan seluruh unit kerja auditi secara langsung di ruangan'], 0, 'Exit Meeting = klarifikasi fakta & bukti terakhir (bukan tawar-menawar hapus temuan valid) + komitmen jadwal tindak lanjut 60 hari!', 'Semua tanggapan dan komitmen pimpinan auditi atas temuan wajib direkam jelas pada Berita Acara Exit Meeting dan LHA.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-penugasan-audit-tujuan-tertentu-42', 'Selain Audit Kinerja dan Audit Keuangan, jenis penugasan audit yang dilakukan khusus untuk memeriksa dugaan penyimpangan spesifik seperti korupsi pengadaan, pemotongan dana bantuan, atau penyalahgunaan wewenang disebut...', ['A. Audit Dengan Tujuan Tertentu (ADTT / Audit Investigatif / Audit Penghitungan Kerugian Keuangan Negara)', 'B. Audit Promosi Pemasaran Komersial', 'C. Survei Kepuasan Kantin Pegawai', 'D. Pelatihan Dasar Calon Pegawai', 'E. Reviu Jadwal Piket Keamanan'], 0, 'ADTT (termasuk Audit Investigatif & PKKN) punya standar pembuktian sangat ketat (pro-justitia jika diserahkan ke APH)!', 'Dalam kasus tindak pidana korupsi, APIP (Inspektorat/BPKP) dan BPK sering berkoordinasi dengan Kejaksaan/Polri/KPK dalam Audit Penghitungan Kerugian Keuangan Negara (PKKN).'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-garansi-pemeliharaan-43', 'Setelah Pekerjaan Konstruksi selesai 100% (PHO — Provisional Hand Over), sebelum Final Hand Over (FHO), penyedia wajib menjalani Masa Pemeliharaan dan menanggung cacat mutu yang dijamin melalui...', ['A. Pemotongan langsung gaji kepala dinas', 'B. Retensi sebesar 5% dari nilai kontrak ATAU menyerahkan Jaminan Pemeliharaan sebesar 5% dari nilai kontrak (untuk pembayaran 100% saat PHO)', 'C. Surat pernyataan lisan mandor proyek tanpa dokumen hukum', 'D. Tidak ada masa pemeliharaan bila proyek dikerjakan di pulau Jawa', 'E. Asuransi jiwa pegawai kementerian'], 1, 'PHO (100% fisik) -> Pembayaran 95% (tahan Retensi 5%) ATAU 100% asal serahkan Jaminan Pemeliharaan 5% sampai FHO selesai (min 6 bln permanen / 3 bln semi)!', 'Audit kerap memeriksa apakah pekerjaan jalan yang retak di masa pemeliharaan telah diperbaiki penyedia atau ditagihkan pencairan retensinya!'],
    ['Pengawasan Urusan Pemda (PPUPD) & Keuangan Desa', 'aud-exp-apip-apip-sp4n-sinergi-44', 'Nota Kesepahaman (MoU) sinergi antara APIP (Inspektorat/BPKP) dengan Aparat Penegak Hukum (Kejaksaan/Polri) mengenai pengaduan masyarakat indikasi korupsi penyelenggaraan pemerintah daerah menetapkan prinsip koordinasi berupa...', ['A. Setiap kesalahan ketik dokumen langsung dipenjara tanpa verifikasi administratif', 'B. Memilah secara objektif antara kesalahan administratif (diselesaikan lewat pembinaan & pengembalian tuntutan perbendaharaan <= 60 hari oleh APIP) dengan perbuatan melawan hukum berniat jahat/mens rea korupsi (ditangani APH)', 'C. APIP melarang APH menyidik kasus OTT tertangkap tangan', 'D. APH menjadi Pejabat Pembuat Komitmen pada proyek konstruksi dinas', 'E. Seluruh pengaduan masyarakat harus dibuang jika tidak bertanda tangan notaris'], 1, 'Prinsip Sinergi APIP–APH: Kesalahan Administratif -> Tindak Lanjut APIP <=60 hari; Mens Rea Korupsi/OTT -> Penegakan Hukum APH!', 'Pemilahan objektif ini mencegah kriminalisasi kebijakan diskresi administratif yang beritikad baik sekaligus memastikan koruptor tetap diproses tegas.'],
    ['Studi Kasus Audit, PBJ & Pengawasan APIP', 'aud-exp-kasus-konsultan-plagiat-45', 'Pada hasil audit jasa konsultansi penyusunan naskah akademik/kajian Rp300 juta di sebuah instansi, tim audit mendapati 85% isi laporan akhir sama persis hasil salin-tempel (plagiat) kajian kabupaten lain tahun 2019 tanpa survei lapangan baru sebagaimana disyaratkan KAK. Rekomendasi APIP adalah...', ['A. Menerima hasil karena tulisannya tampak tebal dan rapi', 'B. Menyatakan hasil pekerjaan tidak memenuhi syarat prestasi KAK (wanprestasi substansi), menunda/meminta pengembalian pembayaran sesuai output tidak sah, menagih perbaikan penuh atau menjatuhkan sanksi Daftar Hitam/denda, dan mengevaluasi pengawasan tim teknis PPK', 'C. Mengganti nama kabupaten pada sampul laporan di ruangan auditor', 'D. Membayar bonus tambahan karena konsultan cepat menyerahkan laporan', 'E. Memerintahkan staf dinas mengetik ulang seluruh laporan diam-diam'], 1, 'Audit Konsultansi = cek substansi & metodologi sesuai KAK (bukan sekadar ada jilid buku laporan)! Plagiarisme KAK = cacat prestasi kontrak!', 'Menggunakan perangkat lunak pendeteksi kemiripan dokumen dan menguji catatan lapangan konsultan adalah praktik CAATs wajib pada audit belanja jasa kajian.'],
    ['Standar Audit Intern (AAIPI) & SPIP (PP 60/2008)', 'aud-exp-matriks-tpp-audit-46', 'Bagaimana peran Penelaahan Sejawat (Peer Review) berkala antar-Inspektorat dalam standar kendali mutu profesi APIP?', ['A. Ajang saling tukar hadiah antarpejabat pengawasan', 'B. Menilai secara objektif kepatuhan proses audit dan mutu KKA/LHA suatu APIP terhadap Standar Audit AAIPI guna menjaga kredibilitas hasil pengawasan', 'C. Mengganti nilai kinerja APBD provinsi secara sepihak', 'D. Membatalkan temuan BPK secara kolektif', 'E. Memindahkan seluruh arsip pengawasan ke pihak ketiga'], 1, 'Penilaian Kualitas Internal & Eksternal (Telaah Sejawat AAIPI minimal tiap 5 tahun) menjamin APIP memenuhi standar profesionalisme tinggi!', 'Hasil telaah sejawat memetakan area perbaikan metodologi audit agar opini dan simpulan APIP dipercaya oleh BPK, KPK, maupun pimpinan nasional.'],
    ['Teknik Audit (Kinerja, Ketaatan, Probity, Reviu LK/RKA)', 'aud-exp-penelusuran-penerimaan-pnbp-47', 'Saat mengaudit akuntabilitas Penerimaan Negara Bukan Pajak (PNBP) atau Retribusi Layanan Daerah yang masih memungut karcis manual di lapangan, risiko pengendalian (control risk) paling tinggi yang wajib diuji auditor adalah...', ['A. Kebocoran penerimaan akibat nomor seri karcis tidak terurut (prenumbered), penyetoran kas terlambat ke rekening kas negara/daerah, atau pencatatan lebih rendah dari jumlah pengunjung riil (understatement)', 'B. Terlalu banyaknya karcis yang dicetak digital terhubung dengan QRIS', 'C. Pegawai terlalu cepat menyetorkan uang di sore hari', 'D. Kelebihan pembayaran pajak pusat ke rekening kas negara', 'E. Penggunaan aplikasi pembayaran nontunai secara penuh'], 0, 'Audit Pendapatan/Retribusi = uji kelengkapan (Completeness): cek karcis prenumbered, uji petik trafik lapangan vs karcis, dan dorong cashless QRIS/Virtual Account!', 'Migrasi penuh ke pembayaran nontunai langsung ke rekening kas daerah menutup celah kebocoran petugas lapangan.'],
    ['Pengadaan Barang/Jasa (Perpres 16/2018 jo Perpres 12/2021)', 'aud-exp-pbj-hps-konsultan-personil-48', 'Dalam pemeriksaan kewajaran biaya langsung personil (billing rate) pada kontrak Jasa Konsultansi Non-Konstruksi, acuan tolok ukur wajar nasional yang umumnya dijadikan kriteria audit PBJ adalah...', ['A. Tarif per jam artis papan atas nasional', 'B. Standar Biaya Masukan (SBM) PMK, pedoman INKINDO yang relevan sesuai kualifikasi & pengalaman riil tenaga ahli terdaftar (CV/SKK/NPWP), beserta konfirmasi kehadiran riil personil inti', 'C. Perkiraan harga tertinggi yang diminta oleh direktur konsultan', 'D. Upah minimum harian buruh lepas tanpa memandang keahlian', 'E. Harga sewa ruangan gedung kantor swasta'], 1, 'Audit Konsultan: cek Billing Rate wajar + kesesuaian bukti ijazah/pengalaman tenaga ahli di dokumen penawaran vs orang yang benar-benar kerja di lapangan (anti pinjam nama/CV)!', 'Temuan paling sering pada proyek konsultan adalah "pinjam bendera / pinjam nama tenaga ahli S2/Ahli Utama", padahal di lapangan dikerjakan staf lulusan baru tanpa kualifikasi.'],
    ['Pengawasan Urusan Pemda (PPUPD) & Keuangan Desa', 'aud-exp-perizinan-oss-audit-49', 'Dalam melakukan pengawasan penyelenggaraan pelayanan perizinan berusaha berbasis risiko (OSS-RBA) oleh DPMPTSP daerah, fokus kepatuhan yang diuji tim APIP/PPUPD adalah...', ['A. Memastikan seluruh perizinan dipersulit manual tanpa lewat sistem OSS', 'B. Ketepatan pemenuhan Norma, Standar, Prosedur, dan Kriteria (NSPK) pusat, kesesuaian jangka waktu fiktif-positif/SLA, ketiadaan pungli di luar PNBP/retribusi resmi, serta efektivitas pengawasan izin pascaterbit', 'C. Mewajibkan setiap warung kecil membayar izin industri berat', 'D. Memungut iuran tambahan bagi tim pengawas di luar DPA', 'E. Menutup sistem OSS daerah saat masa liburan akhir tahun'], 1, 'Pengawasan DPMPTSP = kepatuhan NSPK pusat-daerah + ketepatan SLA OSS + nol pungli + pengawasan kepatuhan pascaterbit!', 'Tanpa pengawasan kepatuhan izin pascaterbit (post-audit lapangan), usaha berisiko tinggi bisa menyalahgunakan kelonggaran deklarasi mandiri OSS.'],
    ['Studi Kasus Audit, PBJ & Pengawasan APIP', 'aud-exp-kasus-aset-hibah-pihak3-50', 'Sebuah dinas menganggarkan belanja barang untuk diserahkan kepada masyarakat/kelompok tani Rp1,2 miliar dengan dokumen usulan nama penerima baru dicari setelah barang dibeli dan sebagian barang masih menumpuk di rumah ketua panitia selama 4 bulan. Temuan & rekomendasi auditor yang tepat adalah...', ['A. Menganggap wajar selama kuitansi pembelian dari toko sudah dibayar penuh', 'B. Mencatat pelanggaran perencanaan belanja hibah/bantuan sosial (calon penerima & lokasi wajib diverifikasi by name by address sebelum penganggaran/pembelian), memerintahkan inventarisasi pengamanan barang segera serta verifikasi penyaluran sah ke penerima berhak, dan menindaklanjuti jika ada barang hilang', 'C. Mengubah kode akun di komputer dari hibah masyarakat menjadi belanja perjalanan dinas', 'D. Membagi rata sisa barang ke pegawai dinas agar gudang bersih', 'E. Menghapus daftar penerima dari laporan keuangan'], 1, 'Belanja untuk diserahkan ke masyarakat/Pemda (526/Hibah-Bansos): Wajib BNBA valid di awal & BAST penyaluran riil (anti penimbunan fiktif)!', 'Barang persediaan bantuan masyarakat yang mengendap di rumah pribadi sangat rentan dialihkan secara ilegal sehingga wajib segera diamankan.']
  ];

  /* ==================== 4. SKB BAHASA INGGRIS KEMENTERIAN (+45 Soal -> Total 105 Soal) ==================== */
  const INGGRIS_EXP = [
    ['Grammar & Structure (Kementerian)', 'ing-exp-subjunctive-01', 'The Minister of Administrative and Bureaucratic Reform recommended that every government agency _____ its public complaint portal with the national SP4N-LAPOR! backbone.', ['A. integrates', 'B. integrate', 'C. integrated', 'D. to integrate', 'E. is integrating'], 1, 'Subjunctive verbs ("recommend/insist/suggest/require that + S + V-bare infinitive"): pakai base verb "integrate" tanpa -s!', 'After verbs of urgency/recommendation ("recommend that"), English formal bureaucratic writing uses the bare infinitive ("integrate", or "should integrate").'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-inversion-notonly-02', 'Not only _____ to accelerate licensing transparency, but it also eliminates redundant paper filing across regional offices.', ['A. the OSS-RBA platform helps', 'B. does the OSS-RBA platform help', 'C. helps the OSS-RBA platform', 'D. the OSS-RBA platform does help', 'E. helping the OSS-RBA platform'], 1, 'Negative/restrictive adverbials di awal kalimat ("Not only", "Seldom", "Never", "Hardly") -> WAJIB Inversi (Aux + Subject + Verb)!', 'Starting with "Not only" requires subject-auxiliary inversion: "Not only DOES + singular subject + bare verb help".'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-conditional-mix-03', 'Had the provincial procurement team conducted a thorough market survey beforehand, the audit dispute regarding the reference price _____ avoided.', ['A. will have been', 'B. would be', 'C. would have been', 'D. has been', 'E. was being'], 2, 'Inversion Conditional Type 3 ("Had + S + V3" = If S had V3) -> Main clause pakai "would have + V3"!', '"Had the team conducted..." represents an unreal past condition (Type 3), requiring "would have been avoided" for a past consequence.'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-participle-clause-04', '_____ under strict Zero Trust security controls, the national data center prevents lateral movement across isolated tenant servers.', ['A. Designing', 'B. Designed', 'C. To design', 'D. Have designed', 'E. Design'], 1, 'Participle awal kalimat: subjek utama "the national data center" DI-rancang (makna PASIF) -> pakai Past Participle V3 ("Designed")!', 'The data center does not design itself; it is designed under strict controls, so the passive participle "Designed" is grammatically required.'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-number-vs-amount-05', 'A large _____ of public policy analysts attended the bilateral ASEAN digital governance symposium in Jakarta yesterday.', ['A. amount', 'B. number', 'C. volume', 'D. quantity', 'E. deal'], 1, 'Countable plural noun ("analysts") -> "a number of"; Uncountable noun -> "an amount of / a great deal of"!', '"Public policy analysts" is countable plural, so "number" is the only precise quantifier; "amount" applies to uncountable nouns.'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-subject-verb-neither-06', 'Neither the head of division nor the two junior auditors _____ authorized to alter electronic audit trail logs.', ['A. is', 'B. are', 'C. was', 'D. has', 'E. does'], 1, 'Korelasi "Neither A nor B / Either A or B": kata kerja mengikuti subjek PALING DEKAT (B = "the two junior auditors" = Jamak -> "are")!', 'With "neither...nor", verb agreement matches the nearer subject ("two junior auditors", plural -> "are authorized").'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-gerund-prep-to-07', 'Civil servants must be committed to _____ impartial service regardless of citizens socioeconomic or regional backgrounds.', ['A. deliver', 'B. delivered', 'C. delivering', 'D. delivers', 'E. be deliver'], 2, 'Jebakan klasik TOEFL/CPNS: "be committed TO", "look forward TO", "object TO", "dedicated TO" -> di sini "to" adalah PREPOSISI -> WAJIB V-ing (Gerund)!', 'In "committed to", the word "to" acts as a preposition rather than an infinitive marker, requiring the gerund "delivering".'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-comparison-thatof-08', 'The broadband penetration rate in urban municipalities remains substantially higher than _____ in remote archipelago regencies.', ['A. those', 'B. that', 'C. it', 'D. this', 'E. which'], 1, 'Perbandingan kata benda tunggal tak terulang ("the penetration rate") memakai "THAT of" (singular) atau "THOSE of" (plural)!', 'To compare apples to apples ("the rate" = singular), use the demonstrative pronoun "that" referring back to "the broadband penetration rate".'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-despite-vs-although-09', '_____ substantial investments in server hardware, fragmented workflows across ministries initially slowed data interoperability.', ['A. Although', 'B. Despite', 'C. Even though', 'D. Whereas', 'E. However'], 1, 'Noun Phrase ("substantial investments...") tanpa Subject+Verb -> pakai Preposisi "Despite / In spite of", BUKAN konjungsi "Although / Even though"!', 'Notice there is no finite verb in the first clause; therefore, the preposition "Despite" is required instead of subordinating conjunctions.'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-subjunctive-essential-10', 'It is imperative that the draft ministerial regulation _____ reviewed by the harmonization team prior to public consultation.', ['A. is', 'B. be', 'C. was', 'D. will be', 'E. being'], 1, '"It is imperative/essential/vital that + S + BE + V3" -> subjunctive pasif memakai bare infinitive "BE"!', 'Mandative adjectives like "imperative that..." trigger the subjunctive mood ("be reviewed").'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-such-so-11', 'The new personal data protection law carries _____ stringent administrative fines that private processors quickly upgraded encryption standards.', ['A. so', 'B. such', 'C. very', 'D. too', 'E. as'], 1, 'Rumus cepat: "SO + adj/adv + that", sedangkan "SUCH + (adj) + NOUN PHRASE + that"! ("stringent administrative fines" = frasa nomina)!', '"Stringent administrative fines" is a plural noun phrase modified by an adjective, which requires "such... that", whereas "so" precedes a lone adjective/adverb.'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-who-vs-whom-12', 'The regional inspectorate summoned the procurement officer _____ the whistleblower identified in the confidential dossier.', ['A. who', 'B. whom', 'C. whose', 'D. which', 'E. what'], 1, 'Cek peran klausa relatif: "the whistleblower (Subject) identified HIM (Object)" -> menggantikan OBJEK orang -> pakai "WHOM"!', 'Because "the whistleblower" is already the subject of "identified", the missing slot is the human object, calling for "whom".'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-hardly-when-13', 'Hardly had the online civil service portal opened at 08:00 a.m. _____ tens of thousands of applicants submitted their files simultaneously.', ['A. than', 'B. when', 'C. until', 'D. since', 'E. while'], 1, 'Pasangan tetap idiom inversi: "Hardly / Scarcely ... WHEN", sedangkan "No sooner ... THAN"!', 'Do not confuse "No sooner... than" with "Hardly/Scarcely... when"; "when" is the exact formal correlative here.'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-along-with-14', 'The Director General, along with three senior legal drafters, _____ scheduled to testify before the parliamentary commission tomorrow.', ['A. are', 'B. were', 'C. is', 'D. have been', 'E. being'], 2, 'Frasa diapit koma ("along with...", "as well as...", "together with...") TIDAK mengubah jumlah subjek utama ("The Director General" = Tunggal -> "is")!', 'Ignore parenthetical prepositional phrases set off by commas; the head noun is singular ("The Director General").'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-causative-have-15', 'Before launching the e-service nationally, the agency will have an independent cybersecurity firm _____ a comprehensive penetration test.', ['A. conducted', 'B. conduct', 'C. to conduct', 'D. conducting', 'E. conducts'], 1, 'Causative Aktif "have + Someone (Agent) + V1 bare infinitive"; sedangkan "get + Someone + TO V1"!', '"Have [agent] [do something]" takes the bare infinitive "conduct", unlike passive "have [object] [done/conducted]".'],
    ['Written Expression (Error Identification)', 'ing-exp-err-number-is-16', 'Identify the incorrect underlined word/phrase: "The number of regional governments adopting open-data dashboards [A. have increased] [B. significantly] [C. since] the implementation of the [D. national mandate]."', ['A. [A] have increased -> seharusnya has increased', 'B. [B] significantly -> seharusnya significant', 'C. [C] since -> seharusnya for', 'D. [D] national mandate -> seharusnya mandate national', 'E. No error in the sentence'], 0, '"THE number of + plural noun" mengambil kata kerja TUNGGAL ("has increased"), sedangkan "A number of" = JAMAK ("have")!', 'The true subject is singular "The number", so "[A] have increased" must be corrected to "has increased".'],
    ['Written Expression (Error Identification)', 'ing-exp-err-parallelism-17', 'Spot the error: "Good fiscal governance requires [A. transparent budgeting], [B. timely procurement execution], and [C. to report financial statements accurately]."', ['A. [A] transparent budgeting -> seharusnya transparently budget', 'B. [B] timely procurement execution -> seharusnya executed timely', 'C. [C] to report financial statements accurately -> seharusnya accurate financial reporting (paralelisme noun phrase)', 'D. Both [A] and [B] are ungrammatical', 'E. The sentence contains no grammatical error'], 2, 'Cek Paralelisme seri list: Noun Phrase + Noun Phrase + Noun Phrase ("...and accurate financial reporting")!', 'Mixing gerund/noun phrases ("transparent budgeting", "timely execution") with an infinitive phrase ("to report...") violates parallel structure.'],
    ['Written Expression (Error Identification)', 'ing-exp-err-redundant-returnback-18', 'Spot the error: "Auditors discovered that several officials failed to [A. return back] unspent [B. travel advances] to the treasury [C. within] the [D. statutory deadline]."', ['A. [A] return back -> redundan, cukup "return"', 'B. [B] travel advances -> seharusnya advancing travels', 'C. [C] within -> seharusnya inside', 'D. [D] statutory deadline -> seharusnya deadline statutory', 'E. No grammatical flaw'], 0, 'Hindari pleonasme TOEFL/Kemen: "return back", "enter into" (ruang fisik), "repeat again", "collaborate together"!', '"Return" already means "give back", making "back" redundant.'],
    ['Written Expression (Error Identification)', 'ing-exp-err-another-vs-other-19', 'Spot the error: "While one ministry prioritizes legacy migration, [A. another ministries] have already [B. deployed] cloud-native APIs to [C. streamline] [D. cross-border trade]."', ['A. [A] another ministries -> seharusnya other ministries', 'B. [B] deployed -> seharusnya deploying', 'C. [C] streamline -> seharusnya streamlining', 'D. [D] cross-border trade -> seharusnya trade cross-borders', 'E. No correction needed'], 0, '"Another" + Singular Countable Noun; "Other" + Plural Noun ("other ministries")!', 'Plural "ministries" cannot be preceded by "another"; it must be "other ministries".'],
    ['Written Expression (Error Identification)', 'ing-exp-err-usedto-20', 'Spot the error: "Civil registry clerks [A. are used to process] manual paper forms, so adapting to biometric tablets [B. initially] [C. posed] minor operational [D. delays]."', ['A. [A] are used to process -> seharusnya are used to processing (terbiasa) atau used to process (dulu biasa)', 'B. [B] initially -> seharusnya initial', 'C. [C] posed -> seharusnya posing', 'D. [D] delays -> seharusnya delaying', 'E. No grammatical error'], 0, 'Bedakan: "used to + V1" (kebiasaan masa lampau) vs "be/get used to + V-ing" (terbiasa pada situasi sekarang)!', 'With the linking verb "are" present ("are used to..."), "to" is a preposition requiring the -ing form "processing".'],
    ['Written Expression (Error Identification)', 'ing-exp-err-despite-of-21', 'Spot the error: "[A. Despite of] limited bandwidth in outer islands, telemedicine clinics [B. successfully] [C. connected] village midwives with [D. specialist physicians]."', ['A. [A] Despite of -> tidak pernah ada "of" setelah "Despite" (seharusnya "Despite" atau "In spite of")', 'B. [B] successfully -> seharusnya success', 'C. [C] connected -> seharusnya connecting', 'D. [D] specialist physicians -> seharusnya physician specialists', 'E. Sentence is fully correct'], 0, 'Hukum mati grammar: DESPITE (tanpa of) = IN SPITE OF!', '"Despite of" is one of the most frequent preposition errors tested in ministerial English exams.'],
    ['Written Expression (Error Identification)', 'ing-exp-err-fewer-vs-less-22', 'Spot the error: "Automation reduced processing errors, resulting in [A. much less] citizen complaints filed [B. at] service desks [C. during] the [D. third quarter]."', ['A. [A] much less -> seharusnya far fewer (karena "complaints" dapat dihitung jamak)', 'B. [B] at -> seharusnya above', 'C. [C] during -> seharusnya while', 'D. [D] third quarter -> seharusnya three quarter', 'E. All parts are correct'], 0, 'Countable plural ("complaints") -> "FEWER / far fewer"; Uncountable ("time/money/friction") -> "LESS"!', 'Because "complaints" is plural and countable, "fewer" (not "less") is standard in formal English.'],
    ['Written Expression (Error Identification)', 'ing-exp-err-whom-as-subject-23', 'Spot the error: "The policy committee commended every regional planner [A. whom] demonstrated [B. measurable impact] in [C. reducing] rural maternal [D. mortality rates]."', ['A. [A] whom -> seharusnya who (berfungsi sebagai subjek dari kata kerja "demonstrated")', 'B. [B] measurable impact -> seharusnya measurably impact', 'C. [C] reducing -> seharusnya reduce', 'D. [D] mortality rates -> seharusnya rate mortalities', 'E. Sentence is error-free'], 0, 'Setelah kata ganti diikuti langsung kata kerja ("_____ demonstrated"), posisi itu adalah SUBJEK -> pakai "WHO"!', 'Because "demonstrated" immediately needs a subject, "who" is required instead of object pronoun "whom".'],
    ['Written Expression (Error Identification)', 'ing-exp-err-double-comparative-24', 'Spot the error: "Public procurement via open e-catalogs is [A. more faster] and substantially [B. more transparent] than [C. conventional manual bidding] [D. procedures]."', ['A. [A] more faster -> double comparative salah, cukup "faster"', 'B. [B] more transparent -> seharusnya transparenter', 'C. [C] conventional manual bidding -> seharusnya bidding conventional manually', 'D. [D] procedures -> seharusnya procedure', 'E. No errors found'], 0, 'Jangan pernah menggabungkan "more" dengan imbuhan "-er" ("more faster", "more better")!', 'One-syllable adjective "fast" takes only the "-er" suffix ("faster"), never "more faster".'],
    ['Written Expression (Error Identification)', 'ing-exp-err-between-among-25', 'Spot the error: "Clear coordination [A. between] the five participating ministries [B. helped prevent] overlapping grants [C. throughout] the [D. fiscal year]."', ['A. [A] between -> lazimnya memakai "among" untuk >= 3 entitas tidak dipasangkan satu-lawan-satu (atau tetap "between" hanya bila merujuk relasi timbal-balik spesifik; dalam tes grammar standar: 2=between, >=3=among)', 'B. [B] helped prevent -> seharusnya help prevented', 'C. [C] throughout -> seharusnya through out of', 'D. [D] fiscal year -> seharusnya year fiscally', 'E. Completely valid without adjustment'], 0, 'Aturan standar grammar ujian: "between" untuk 2 pihak; "among" untuk >= 3 pihak secara kolektif!', 'For collective coordination among five ministries, standardized English grammar tests expect "among".'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-mitigate-26', 'In ministerial risk management guidelines, agencies are instructed to "mitigate" single points of failure before system launch. The closest synonym for "mitigate" in this context is...', ['A. exacerbate', 'B. alleviate / reduce the severity of', 'C. ignore permanently', 'D. replicate rapidly', 'E. monetize'], 1, '"Mitigate" = meredam/mengurangi dampak keparahan risiko (lawan dari "aggravate/exacerbate")!', 'Risk mitigation focuses on reducing either the likelihood or the impact severity of an adverse event.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-stringent-27', 'Cross-border transfer of biometric citizen records is prohibited unless the recipient jurisdiction guarantees "stringent" statutory safeguards. "Stringent" means...', ['A. lenient and informal', 'B. rigorous, strict, and exacting', 'C. obsolete and vague', 'D. temporary and optional', 'E. costly without reason'], 1, '"Stringent" = ketat / keras / berstandar tinggi (strict & rigorous)!', 'Common in GDPR, UU PDP, and regulatory compliance passages.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-streamline-28', 'One core goal of Indonesia\'s Bureaucratic Reform is to "streamline" overlapping permit stages for small businesses. Here, "streamline" implies...', ['A. adding extra review signatures to slow down approvals', 'B. simplifying and making a process faster and more efficient', 'C. postponing digitalization for five fiscal cycles', 'D. privatizing municipal courts', 'E. complicating technical specifications'], 1, '"Streamline" = merampingkan / menyederhanakan alur birokrasi agar lebih cepat & lincah!', 'Frequently paired with "bureaucratic bottlenecks" and "red tape" in OECD governance texts.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-redtape-29', 'Foreign investors frequently cite excessive "red tape" rather than tax rates as the primary obstacle to starting factories. The idiom "red tape" refers to...', ['A. physical security barriers around ministry compounds', 'B. excessive bureaucracy and rigid adherence to formal paperwork that delays action', 'C. official emergency funding reserved for disasters', 'D. diplomatic treaties signed in Southeast Asia', 'E. digital encryption certificates'], 1, '"Red tape" = birokrasi berbelit-belit / aturan prosedural kaku yang memperlambat layanan!', 'Coined historically from red cloth tape used to bind thick bundles of legal/official papers.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-interoperable-30', 'National e-government strategy demands that regional health records be "interoperable" with social assistance registries. This means the two systems must be able to...', ['A. operate strictly offline on separate floppy disks', 'B. exchange and use shared data seamlessly across different platforms under common standards', 'C. block external audits indefinitely', 'D. share identical visual logos without backend APIs', 'E. replace all medical personnel with chatbots'], 1, '"Interoperable" = mampu saling bertukar dan memanfaatkan data lintas sistem yang berbeda dengan standar metadata selaras!', 'Interoperability via SPLP prevents siloed data islands across government bodies.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-disbursement-31', 'Fiscal reports noted sluggish capital "disbursement" during the first two quarters due to delayed tender documents. "Disbursement" refers to...', ['A. cancellation of tax revenue targets', 'B. the actual payout / expenditure of allocated public funds', 'C. borrowing money from commercial lenders', 'D. auditing warehouse inventory stocks', 'E. archiving physical receipts'], 1, '"Disbursement" = pencairan / realisasi pengeluaran anggaran kas!', 'Used ubiquitously in World Bank, Kemenkeu, and Bappenas reports alongside "budget execution".'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-accountable-32', 'An "equitable" fiscal transfer formula adjusts grants so under-resourced outer islands can reach minimum public service standards. "Equitable" is closest in meaning to...', ['A. identical in every dollar without context', 'B. fair and impartial according to proportional need', 'C. secretive and arbitrary', 'D. biased toward metropolitan centers', 'E. purely profit-driven'], 1, '"Equitable" = berkeadilan proporsional sesuai kebutuhan (berbeda dengan "equal" yang membagi sama rata angka mentah)!', 'HKPD intergovernmental grants use equitable formulas accounting for fiscal capacity and service delivery costs.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-obsolete-33', 'Maintaining "obsolete" legacy servers without vendor security patches exposes citizen registries to ransomware attacks. "Obsolete" means...', ['A. cutting-edge and newly released', 'B. outdated and no longer supported or useful', 'C. highly redundant and fault-tolerant', 'D. economically indispensable', 'E. encrypted end-to-end'], 1, '"Obsolete" = usang / ketinggalan zaman (outdated)!', 'System modernization targets phasing out obsolete software stacks and unsupported operating systems.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-viable-34', 'Policy analysts rejected building an unsubsidized toll road in a sparsely populated valley because it was not financially "viable". "Viable" means...', ['A. politically controversial', 'B. capable of working successfully and practically feasible', 'C. completely free of environmental impact', 'D. guaranteed to fail quickly', 'E. hidden from parliamentary review'], 1, '"Viable" = layak secara praktis/ekonomi untuk dilaksanakan & bertahan (feasible)!', 'Often appears in feasibility studies (FS) and Public-Private Partnership (KPBU) assessments.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-mandate-35', 'Under Presidential Regulation No. 39/2019, the Statistics Agency holds a clear "mandate" as the national statistical data steward. Here, "mandate" signifies...', ['A. an optional informal hobby', 'B. an official authority and legal instruction granted to carry out a responsibility', 'C. a temporary suspension of service', 'D. a private commercial license', 'E. an anonymous public complaint'], 1, '"Mandate" = mandat / kewenangan tugas resmi berbasis hukum!', 'Core public administration term distinguishing statutory authority from voluntary initiatives.'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-govtech-1-36', 'Read the passage: "While early e-government initiatives simply digitized paper forms ministry by ministry, modern GovTech centers on user journeys—such as registering a birth or launching an enterprise—where backend agencies automatically exchange verified records through secure APIs without forcing citizens to resubmit identical documents." What is the primary contrast drawn by the author?', ['A. Modern GovTech bans all ministries from using any internet APIs', 'B. Early e-government digitized siloed forms separately, whereas modern GovTech integrates backend data around end-to-end citizen life events', 'C. Citizens prefer filling out identical physical forms at 10 different buildings', 'D. GovTech abolishes identity verification entirely to save server space', 'E. Only private banks participate in modern digital public services'], 1, 'Cek kata kunci kontras ("While... modern GovTech centers on..."): awal = meniru kertas secara terpisah (silo); modern = terpusat pada alur warga + integrasi API lintas instansi!', 'Option B captures the exact contrast between agency-silo digitization and citizen-journey backend interoperability.'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-govtech-2-37', 'Based on the same GovTech passage ("where backend agencies automatically exchange verified records... without forcing citizens to resubmit identical documents"), which principle of digital public infrastructure does the author imply?', ['A. Once-Only Data Principle (warga tidak perlu mengulang serah data yang sudah ada di negara)', 'B. Complete elimination of API security encryption', 'C. Mandatory manual photocopying of every database row', 'D. Isolating municipal servers from national networks', 'E. Charging citizens per API call between ministries'], 0, 'Tidak menyerahkan dokumen berulang-ulang kepada instansi berbeda = "Once-Only Principle" dalam SPBE/GovTech!', 'Interoperable backend registries operationalize the Once-Only Principle while cutting citizen transaction costs.'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-ai-reg-1-38', 'Read the passage: "Deploying generative AI chatbots on tax and welfare portals can cut citizen wait times drastically, yet raw models risk hallucinating non-existent exemptions or leaking training prompts. Therefore, leading administrations adopt Retrieval-Augmented Generation (RAG) grounded strictly in vetted statutory databases, accompanied by mandatory source citations and human escalation routes for complex cases." Why do public administrations favor RAG over raw generative models?', ['A. Raw models never require any electricity or computing power', 'B. RAG restricts outputs to verified official statutes, attaches citations, and pairs automation with human review to curb hallucinations', 'C. RAG allows citizens to rewrite tax legislation freely inside chat boxes', 'D. Human escalation routes eliminate all internet browsers', 'E. Raw models are legally forbidden from understanding Indonesian grammar'], 1, 'Cari kalimat alasan ("yet raw models risk... Therefore, leading administrations adopt RAG..."): membatasi halusinasi lewat basis regulasi terverifikasi + sitasi + eskalasi manusia!', 'Reading questions often use "Therefore" to flag the core rationale of a technical policy choice.'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-ai-reg-2-39', 'In the generative AI passage above, the word "vetted" in "vetted statutory databases" is closest in meaning to...', ['A. randomly scraped from social media forums', 'B. carefully examined, verified, and officially approved', 'C. permanently deleted due to corruption', 'D. encrypted without any readable text', 'E. translated informally by unverified interns'], 1, '"Vetted" = sudah ditelaah, diperiksa kelayakan/kebenarannya, dan disahkan secara resmi!', 'Vetting data sources before indexing prevents outdated or conflicting regulations from poisoning AI answers.'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-pdp-1-40', 'Read the passage: "Unlike traditional data backups stored passively on office tapes, modern cyber resilience combines immutable off-site snapshots with routine restoration drills. Many institutions discover too late that having terabytes of daily backups provides zero protection if ransomware encrypts connected backup drives or if staff have never tested recovery-time objectives (RTO)." What main warning does the passage convey?', ['A. Tape backups are permanently indestructible against fire and flood', 'B. Backups are ineffective for cyber resilience unless stored immutably offline/isolated and regularly tested through recovery drills', 'C. Ransomware cannot encrypt files inside office networks', 'D. Institutions should stop taking daily backups altogether to focus on drills', 'E. Measuring RTO guarantees hackers will never attempt phishing'], 1, 'Inti peringatan ("provides zero protection if..."): backup saja tidak cukup — wajib IMMUTABLE (terisolasi tak bisa dienkripsi ulang) + rutin uji restore (RTO)!', 'Focus on the conditional warning structure ("provides zero protection if...").'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-fiscal-1-41', 'Read the passage: "Intergovernmental fiscal grants frequently underperform when local treasuries receive funds only in the final quarter, sparking hasty year-end spending on low-impact supplies. Multi-year performance contracts tied to milestone disbursements—rewarding early procurement planning and measurable service outcomes—consistently lift public infrastructure quality." According to the passage, what causes hasty low-impact spending?', ['A. Excessively high quality of local roads', 'B. Delayed fund transfers arriving late in the final fiscal quarter', 'C. Multi-year performance contracts with clear outcomes', 'D. Early procurement planning in January', 'E. Transparent public service milestones'], 1, 'Cari kata sebab langsung ("when local treasuries receive funds only in the final quarter, sparking..."): pencairan telat di kuartal IV memicu "kejar serapan" kualitas rendah!', 'Connecting cause ("receive funds only in Q4") directly to effect ("hasty year-end spending") pins Option B unambiguously.'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-green-1-42', 'Read the passage: "Green public procurement (GPP) goes beyond purchasing energy-efficient office bulbs; it evaluates total life-cycle cost—factoring maintenance, electricity draw, disposal hazards, and carbon footprint—so slightly costlier eco-certified equipment often saves more public money over a five-year horizon." Why can eco-certified equipment save public money despite a higher upfront price?', ['A. Suppliers donate spare parts illegally under the table', 'B. Evaluating life-cycle cost reveals lower long-term operational, energy, maintenance, and disposal expenses over five years', 'C. Five-year budgets exclude all electricity expenses entirely', 'D. Energy-efficient bulbs never require replacement for 500 years', 'E. Upfront purchase prices are exempt from official accounting'], 1, 'Life-Cycle Cost (Biaya Siklus Hidup): harga beli awal sedikit lebih tinggi tertutup hemat listrik + perawatan + limbah dalam 5 tahun!', 'Total Cost of Ownership (TCO / LCC) is a key benchmark in sustainable government procurement.'],
    ['Reading: Kebijakan Digital & Siber', 'ing-exp-read-merit-1-43', 'Read the passage: "While competitive entrance exams filter baseline cognitive ability, retaining top public-sector talent depends equally on transparent promotion pathways, constructive annual performance coaching, and protection from arbitrary political transfers." Which statement would the author most strongly agree with?', ['A. Once civil servants pass entry tests, agencies no longer need coaching or fair promotion rules', 'B. Cognitive entry testing alone is insufficient unless complemented by fair career progression, feedback, and merit-based protection', 'C. Political transfers always raise employee morale and institutional memory', 'D. Entrance exams should be replaced entirely with informal interviews', 'E. Salary levels are the only variable affecting employee retention'], 1, 'Pola argumen "While A filters baseline, retaining talent depends equally on B, C, D": tes masuk penting tapi TIDAK cukup tanpa keadilan karier & perlindungan merit!', 'Avoid extreme distractors like "only variable" or "replaced entirely"; pick the balanced synthesis Option B.'],
    ['Grammar & Structure (Kementerian)', 'ing-exp-cleft-it-was-44', 'It was the regional health office\'s rapid contact tracing network _____ prevented the localized outbreak from spreading into neighboring provinces.', ['A. who', 'B. what', 'C. that', 'D. whom', 'E. whose'], 2, 'Cleft sentence penekanan ("It was [non-human noun phrase] THAT [verb]..."): gunakan "that" (atau "which" non-cleft, standar cleft = "that")!', 'For non-human emphasized subjects in "It is/was... that..." cleft sentences, "that" is standard formal usage.'],
    ['Vocabulary Pemerintahan & Teknologi', 'ing-exp-vocab-transparency-45', 'Because internal audit findings remained "confidential" until formal exit confirmation, draft working papers were locked inside encrypted folders. The antonym (opposite) of "confidential" is...', ['A. classified', 'B. public / open', 'C. sensitive', 'D. restricted', 'E. proprietary'], 1, 'Antonym (lawan kata) dari "confidential" (rahasia terbatas) adalah "public / open" (terbuka untuk umum)!', 'Watch test prompts carefully for "closest meaning/synonym" versus "opposite/antonym".']
  ];

